// ---------- Multijoueur : code de partie à 5 lettres (sans caractères ambigus) ----------
function makeGameCode() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let code = "";
  for (let i = 0; i < 5; i++) code += chars[Math.floor(Math.random() * chars.length)];
  return code;
}

// ---------- Amis ----------
// L'identifiant du joueur : six chiffres, precedes d'un dièse. Les pseudos ne sont pas
// uniques — deux CARNAGE peuvent coexister — et c'est le numero qui distingue.
//
// Des CHIFFRES et non des lettres, pour trois raisons : sur telephone le champ appelle le
// pave numerique au lieu du clavier complet ; un nombre se dicte de tete, en deux groupes
// de trois ; et aucun caractere ne prete a confusion (pas de O contre 0, de I contre 1).
// Six chiffres font un million d'identifiants : passer a sept est une ligne a changer.
//
// Tire au hasard et STOCKE (dans le profil et dans l'index /codesAmi), jamais derive de
// l'identite : un hachage ne se « retire » pas quand deux joueurs tombent sur le meme.
// Au hasard et non a la suite : un numero sequentiel dirait le nombre de joueurs et
// l'ordre d'arrivee, et exigerait un compteur partage que tout le monde se disputerait.
// HUIT depuis le 03/09, et non six : six chiffres, c etait un espace d un million,
// qu un million de lectures suffisait a balayer -- l annuaire complet des uid, et par
// lui le profil de chacun. Huit rendent le balayage cent fois plus cher. Les numeros
// deja distribues a six chiffres sont reattribues au chargement.
const IDENTIFIANT_CHIFFRES = 8;
function makeCodeAmi() {
  let code = "";
  for (let i = 0; i < IDENTIFIANT_CHIFFRES; i++) code += Math.floor(Math.random() * 10);
  return code;
}
// Affichage : le dièse fait partie de la lecture, jamais du code stocke.
function codeAmiLisible(code) {
  return code ? "#" + code : "";
}
// L'identifiant ne s'affiche pas d'un bloc : il se COMPOSE, caractere par caractere, de
// gauche a droite, une fois le nom ecrit. Les deux nombres vivent ici ensemble pour que
// le retard de la phrase qui suit se calcule sur eux, et tombe toujours juste apres le
// dernier chiffre.
const ID_ANIM_DEPART = 340;   // ms de silence avant le premier caractere
const ID_ANIM_PAS = 190;      // ms entre deux caracteres
const ID_ANIM_APRES = 260;    // ms entre le dernier chiffre et la phrase d'explication
const ID_ANIM_NOTE_MS = 800;  // duree du fondu de la phrase (pseudo-note-entre)
// Le devoilement entier, de la premiere seconde de silence au dernier point de la phrase.
// C'est ce que l'ecran de saisie doit tenir avant de rendre la main.
const ID_ANIM_TOTAL = ID_ANIM_DEPART + (IDENTIFIANT_CHIFFRES + 1) * ID_ANIM_PAS
  + ID_ANIM_APRES + ID_ANIM_NOTE_MS;

// A la saisie, le joueur n'a que des chiffres a taper : le dièse est deja a l'ecran. On
// le tolere quand meme s'il colle un identifiant complet.
function nettoyerCodeAmi(brut) {
  return String(brut || "").replace(/[^0-9]/g, "").slice(0, IDENTIFIANT_CHIFFRES);
}
const AMIS_MAX = 20;                       // borne les lectures a l'ouverture du profil
const DEMANDES_PAR_JOUR = 20;              // envoyees ; au-dela, c'est du demarchage
const RENVOI_MIN_MS = 24 * 60 * 60 * 1000; // une demande ignoree ne se renvoie pas avant un jour
const CLE_DEMANDES = "emprise-demandes";   // compteur du jour et dates d'envoi, par appareil
// Motifs de signalement. Apple exige un moyen de signaler des qu'un joueur voit du contenu
// ecrit par un autre — ici le pseudo. La liste reste courte : on signale, on ne plaide pas.
const MOTIFS_SIGNALEMENT = [
  ["pseudo", "Nom offensant"],
  ["triche", "Triche"],
  ["comportement", "Comportement en partie"],
  ["autre", "Autre"],
];
// Compteur d'envois, garde sur l'appareil : { jour: "2026-08-23", n: 3, envois: { uid: t } }.
function lireEnvois() {
  try {
    const v = JSON.parse(localStorage.getItem(CLE_DEMANDES) || "{}");
    const jour = new Date().toISOString().slice(0, 10);
    if (v.jour !== jour) return { jour, n: 0, envois: v.envois || {} };
    return { jour, n: v.n || 0, envois: v.envois || {} };
  } catch (e) { return { jour: new Date().toISOString().slice(0, 10), n: 0, envois: {} }; }
}
function ecrireEnvois(v) {
  try { localStorage.setItem(CLE_DEMANDES, JSON.stringify(v)); } catch (e) { /* tant pis */ }
}
const DEFI_PERIME_MS = 10 * 60 * 1000;     // un defi non releve en dix minutes s'efface
// Le bandeau du hub ne dure que dix secondes, la ou le defi en vaut dix minutes. C'est
// voulu : il annonce, il n'attend pas. Passe ce delai il se replie sur la pastille des
// Amis, qui reste allumee jusqu'a la peremption reelle.
// L'Adoubement : la ceremonie qui donne son titre au Commandant, une seule fois dans sa
// vie de joueur. Deux nombres, le temps de la scene et celui de son effacement.
const ADOUBEMENT_MS = 2400;
const ADOUBEMENT_SORTIE_MS = 400;
// Le nom ne se tronque JAMAIS : c'est le sujet meme de l'ecran. Il maigrit plutot que de
// se couper, et le moins possible.
// Les paliers sont MESURES au navigateur, en Cinzel gras avec l'interlettrage de 0.14em,
// sur le plus etroit des telephones vises : 375 px moins 48 de marge, soit 327 utiles.
// A 30 px, treize caracteres en occupent 323 et quinze en demanderaient 377. Chaque
// palier ramene donc le nom autour de 300 px, ce qui laisse une respiration a chacun.
function tailleAdoubement(nom) {
  const n = (nom || "").length;
  if (n <= 12) return 30;
  if (n === 13) return 28;
  if (n === 14) return 26;
  return 24;
}

const DEFI_BANDEAU_MS = 10000;
const DEFI_GLISSE_MS = 250;                // son entree et sa sortie, par le bas
const EN_LIGNE_MS = 3 * 60 * 1000;         // vu il y a moins de trois minutes = en ligne
// ---------- Le rythme d un tour (01/09) ----------
// Trois delais de PRESENTATION, reunis ici pour qu on les lise d un coup. Ce
// ne sont PAS les chronos d equite du jeu en ligne (TURN_SECONDS, le forfait,
// l abandon) : ceux-la vivent ailleurs et ne bougent pas avec ceux-ci.
//   - RYTHME_REFLEXION_ECHO_MS : l Echo attend avant de poser, comme un
//     adversaire qui reflechit. Il attend AUSSI la fin d une chaine d Onde en
//     cours, plus 400 ms, si elle depasse ce plancher.
//   - RYTHME_POSE_ECHO_MS : entre la pose de l Echo et ses captures. Cale sur
//     l animation card-land-bot (46 % de 3,5 s) : la carte finit d atterrir
//     AVANT que quoi que ce soit ne bascule. A changer avec elle, jamais seul.
//   - RYTHME_POSE_JOUEUR_MS : entre MA pose et mes captures. C etait zero --
//     la carte tombait et le plateau basculait dans la meme image, on ne
//     lisait ni l une ni l autre. Quatre cents millisecondes pour voir la
//     pose, puis ce qu elle provoque.
const RYTHME_REFLEXION_ECHO_MS = 3200;
const RYTHME_POSE_ECHO_MS = 1610;
const RYTHME_POSE_JOUEUR_MS = 400;
// Le pivot de capture, en millisecondes : le miroir de --tour-duree, qui vit dans le
// CSS. Les deux doivent dire la meme chose -- la file de presentation en ligne compte
// ce pivot dans le temps qu un coup occupe l ecran. Une sonde le verifie.
const PIVOT_CAPTURE_MS = 1000;
// Portee (02/09) : PORTEE_DEPART_MS apres le maillon (la carte posee a fini
// d atterrir), la fleche apparait au-dessus de l Archer et y reste
// PORTEE_ARMEMENT_MS (fondu en opacite : c est cette pause qui attire l oeil),
// puis vole PORTEE_VOL_MS ; la cible ne pivote qu a l impact. Dans une chaine
// d Onde, un tir retient d autant les maillons suivants. Pense pour un debutant :
// 350 ms de vol se rataient.
const PORTEE_DEPART_MS = 700;
const PORTEE_ARMEMENT_MS = 150;
const PORTEE_VOL_MS = 600;
const PORTEE_TEMPS_MS = PORTEE_DEPART_MS + PORTEE_ARMEMENT_MS + PORTEE_VOL_MS;
// Cendres (02/09) : la carte attiree avance CASE PAR CASE -- un glissement de
// CENDRES_PAS_MS par case, une pause de CENDRES_PAUSE_MS entre deux pas (pas
// apres le dernier). Trois cases : 1 200 ms. Cinq pas au plus (plateau 6 x 6).
const CENDRES_PAS_MS = 300;
const CENDRES_PAUSE_MS = 100;
const CENDRES_PAS_MAX = 5;
function nbPasCendres(steps) { return Math.min(CENDRES_PAS_MAX, Math.max(1, steps || 1)); }
function dureeTrajetCendres(steps) { return nbPasCendres(steps) * (CENDRES_PAS_MS + CENDRES_PAUSE_MS) - CENDRES_PAUSE_MS; }

// La file de presentation en ligne (02/09). Une resolution recue du serveur se joue
// a son rythme normal, ou ne se joue pas -- jamais entre les deux. Elle se joue tout
// de suite si l ecran est libre ; sinon elle attend son tour dans la file ; et si le
// retard est trop grand (onglet cache, coup vieux de plus de PRESENTATION_RETARD_MAX_MS,
// plus de PRESENTATION_FILE_MAX en attente), on saute a l etat courant sans animation.
// L etat autoritaire (plateau, tour, chronos, fin de partie) est applique AVANT et
// n attend jamais l affichage.
// LE PLAFOND DE RETARD VISIBLE (03/09) : le joueur ne doit jamais voir le plateau avec
// plus de trois secondes de retard sur l etat du serveur, quoi qu il arrive. C est la
// regle, et tout le reste s y plie.
const PRESENTATION_RETARD_MAX_MS = 3000;
// UNE seule place d attente, et c est ce qui borne le retard par construction :
// attenteMs ne mesure que la presentation EN COURS, pas celles deja en file. Avec deux
// places, deux presentations de trois secondes faisaient six secondes d attente reelle,
// et le compte des elements ne disait rien de ce retard-la -- c est ainsi qu il grimpait
// a une minute sans que la file paraisse pleine. Avec une place, l attente maximale est
// exactement le plafond : la presentation en cours, puis la sienne.
const PRESENTATION_FILE_MAX = 1;
function decisionPresentation({ occupe, cache, ageMs, enAttente, attenteMs }) {
  if (cache || ageMs > PRESENTATION_RETARD_MAX_MS) return "rattraper";
  if (!occupe && enAttente === 0) return "jouer";
  if (attenteMs > PRESENTATION_RETARD_MAX_MS) return "rattraper";
  if (enAttente + 1 > PRESENTATION_FILE_MAX) return "rattraper";
  return "enfiler";
}
// L identifiant d un coup commence par son horodatage (Date.now() a l ecriture) :
// un coup vieux (reprise, reconnexion, onglet revenu) ne s anime pas, il s applique.
function ageDuCoup(id) {
  const t = Number(String(id || "").split("-")[0]);
  return Number.isFinite(t) && t > 0 ? Math.max(0, Date.now() - t) : 0;
}
// Un nom venu d'un autre joueur passe par le filtre ; « Adversaire », le repli des
// etiquettes de camp, sonnerait faux pour un ami.
function nomAffiche(brut) {
  return pseudoAffichable(brut) || "Commandant";
}
function horodatageMs(v) {
  return v && typeof v.toMillis === "function" ? v.toMillis() : 0;
}

