const STANDARD_ROWS = 4, STANDARD_COLS = 5;
const TEST_ROWS = 6, TEST_COLS = 6; // 36 cases, uniquement en mode test
function setBoardSize(rows, cols) { ROWS = rows; COLS = cols; CELLS = rows * cols; }

