// Petit utilitaire réutilisé partout où un Ordre "prochainement" doit être écarté
// (tirages aléatoires, draft, tournoi) — un Ordre sans status explicite est traité
// comme disponible, pour rester compatible si status venait à manquer quelque part.
// Miroir synchrone des acces anticipes achetes (bourse.accesAnticipe) : cette
// fonction est appelee partout, souvent hors de portee de l'etat React et toujours
// en synchrone. loadBourse et l'achat le tiennent a jour.
let accesAnticipesLocaux = new Set();
function isOrderAvailable(order) {
  if (order.status !== ORDER_STATUS.COMING_SOON) return true;
  // L'acces anticipe rend l'Ordre jouable ICI, pour CE joueur : choix de main,
  // drafts locaux, tournoi solo, quetes. Les tirages PARTAGES avec un adversaire
  // (main commune de Confluence en ligne) passent par tirerDeuxOrdresCommuns,
  // volontairement sourde a ce miroir.
  return accesAnticipesLocaux.has(order.key);
}

// Le roster OFFICIEL : tout ORDERS sauf les Ordres "prochainement", fige au
// chargement du module -- donc JAMAIS les acces anticipes locaux, et c'est voulu :
// il sert la ou le roster doit etre le meme pour tout le monde (bac a sable, drafts
// de secours). Pour la disponibilite DU joueur, appeler isOrderAvailable.
const AVAILABLE_ORDERS = ORDERS.filter(isOrderAvailable);

// Candidats en cours d'évaluation : jouables en bac à sable seulement. Ils sont exclus
// d'AVAILABLE_ORDERS (statut "prochainement") et masqués des écrans de sélection, pour
// ne pas polluer les parties normales, la Confluence, le tournoi ni le mode Histoire.
const ORDRES_A_L_ESSAI = ORDERS.filter((o) => o.essai === true);

// Un Ordre scelle se devoile a l'ouverture de la fenetre d'acces anticipe (vrai
// nom, portrait sans assombrissement) et LE RESTE apres l'heure de sortie : entre
// la sortie et la bascule manuelle du status, il ne se rescelle pas -- seul le
// bouton d'achat meurt a l'heure dite (fenetreAccesAnticipe). Une fois status
// bascule, ces deux fonctions redeviennent transparentes.
function ordreDevoile(order) {
  if (order.status !== ORDER_STATUS.COMING_SOON || !order.releaseDate) return false;
  return Date.now() >= order.releaseDate.getTime() - ACCES_ANTICIPE.fenetreHeures * 3600 * 1000;
}
function nomOrdreAffiche(order) {
  return ordreDevoile(order) && order.nom ? order.nom : order.name;
}

// Vrai décompte en direct (jours/heures/minutes/secondes) pour un Ordre
// "prochainement" avec une date de sortie prévue — se met à jour chaque
// seconde tant que la carte est affichée, via son propre petit minuteur.
function CountdownLabel({ order }) {
  const [now, setNow] = useState(() => new Date());
  useEffect(() => {
    if (!order.releaseDate) return;
    const id = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(id);
  }, [order.releaseDate]);

  if (!order.releaseDate) return "Ordre encore scellé par la Faille, son heure viendra.";
  const diffMs = order.releaseDate - now;
  if (diffMs <= 0) return "Prochainement, son heure est presque venue...";
  const totalSeconds = Math.floor(diffMs / 1000);
  const days = Math.floor(totalSeconds / 86400);
  const hours = Math.floor((totalSeconds % 86400) / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  const pad = (n) => String(n).padStart(2, "0");
  return `Prochainement : ${days}j ${pad(hours)}h ${pad(minutes)}m ${pad(seconds)}s`;
}


// Le decompte du panneau : quatre cadrans plutot qu une phrase. Meme minuteur d une
// seconde que CountdownLabel, qui sert lui a la ligne de description des cartes.
function OrdreDecompte({ order }) {
  const [maintenant, setMaintenant] = useState(() => Date.now());
  useEffect(() => {
    if (!order.releaseDate) return;
    const id = setInterval(() => setMaintenant(Date.now()), 1000);
    return () => clearInterval(id);
  }, [order.releaseDate]);
  if (!order.releaseDate) {
    return <div className="ordre-detail-parties">Son heure viendra.</div>;
  }
  const reste = order.releaseDate - maintenant;
  if (reste <= 0) {
    return <div className="ordre-detail-bientot-proche">Son heure est venue.</div>;
  }
  const total = Math.floor(reste / 1000);
  const jours = Math.floor(total / 86400);
  const cadrans = [
    [jours, "j"],
    [Math.floor((total % 86400) / 3600), "h"],
    [Math.floor((total % 3600) / 60), "m"],
    [total % 60, "s"],
  ];
  return (
    <div className="ordre-decompte" role="timer" aria-label={`Disponible dans ${jours} jours`}>
      {cadrans.map(([valeur, unite]) => (
        <span key={unite}>
          <b>{String(valeur).padStart(2, "0")}</b>{unite}
        </span>
      ))}
    </div>
  );
}

// Vignette d'un Ordre "prochainement". Le portrait réel n'est pas une image
// pré-assombrie : c'est le vrai portrait, poussé au contraste par CSS jusqu'à ne
// laisser qu'une gravure. Une aura respire derrière lui, un balayage lumineux le
// traverse au survol. Sur mobile :hover n'existe pas, d'où l'état "peek"
// déclenché au toucher et relâché après 1,1 s.
// Le jour de la sortie, il suffit de passer status à AVAILABLE : le teaser, le
// cadenas et le compte à rebours disparaissent d'eux-mêmes, le portrait
// s'affiche en clair. Aucune image à remplacer.
// Fait defiler les textes d'attente. Une seule animation, sur opacity et transform,
// relancee a chaque changement par la cle React : rien ne tourne en boucle.
// Melange de Fisher-Yates sur les INDICES. On melange une fois, au montage, puis on
// parcourt : tirer au hasard a chaque changement ramenait la meme astuce deux fois de
// suite une fois sur douze, et cela se remarque immediatement.
function melangerIndices(n) {
  const l = Array.from({ length: n }, (_, i) => i);
  for (let i = l.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const g = l[i]; l[i] = l[j]; l[j] = g;
  }
  return l;
}

function RecitsAttente({ actif, pleinEcran }) {
  const [ordre] = useState(() => melangerIndices(ASTUCES.length));
  const [pos, setPos] = useState(0);
  useEffect(() => {
    if (!actif) return;
    const t = setInterval(() => setPos((p) => (p + 1) % ordre.length), ASTUCE_MS);
    // Sans ce nettoyage, le minuteur survivait au lancement de la partie et continuait
    // d'appeler setPos sur un composant demonte.
    return () => clearInterval(t);
  }, [actif, ordre.length]);
  if (!actif) return null;
  return (
    <div className={`recit-attente ${pleinEcran ? "plein-ecran" : ""}`} role="status" aria-live="polite">
      <div className="recit-genre">Astuce</div>
      {/* La cle force le remontage a chaque changement : c'est elle qui rejoue le fondu. */}
      <p key={pos} className="recit-texte">{ASTUCES[ordre[pos]]}</p>
    </div>
  );
}

// Portrait d'un Ordre dont la couleur monte comme une maree, a la hauteur de la maitrise.
// Deux couches : le portrait grise en dessous, le portrait en couleur par-dessus, decoupe
// a la hauteur voulue avec une crete ondulee qui derive sans fin. Un voile de la couleur
// de l'Ordre teinte la partie remplie, pour que la vague soit bien LA couleur de la carte.
// Le niveau monte depuis zero a l'apparition : on voit la maree arriver.
function VagueMaitrise({ order, taux, grand }) {
  const [niveau, setNiveau] = useState(0);
  const [cote, setCote] = useState(0);
  const ref = useRef(null);
  useEffect(() => {
    const t = setTimeout(() => setNiveau(taux), 60);
    return () => clearTimeout(t);
  }, [taux]);
  // Le portrait couleur doit mesurer la carte entiere : on lit sa hauteur et on la suit
  // si la fenetre change.
  useEffect(() => {
    const el = ref.current; if (!el) return;
    // clientHeight : l interieur du cadre, bordure exclue — c est la que vivent les
    // portraits. La HAUTEUR et non la largeur : la carte n est plus toujours carree (le
    // detail l affiche en 3/4), et c est la hauteur que le portrait couleur doit epouser.
    const lire = () => setCote(el.clientHeight);
    lire();
    const ro = typeof ResizeObserver !== "undefined" ? new ResizeObserver(lire) : null;
    if (ro) ro.observe(el);
    return () => { if (ro) ro.disconnect(); };
  }, []);
  const couleur = MAITRISE_COULEURS[order.key] || "rgba(203,164,86,0.8)";
  // Une seule partie vaut deja une lame d'eau visible : a 1 % on ne voyait rien. Et a
  // 100 %, la crete passe AU-DESSUS du cadre : le portrait est entierement en couleur,
  // sans bande grise ni vague qui derive en haut d'un Ordre pourtant acheve.
  const plein = niveau >= 1;
  const hauteur = niveau === 0 ? 0 : plein ? 130 : Math.max(6, Math.round(niveau * 100));
  return (
    <div ref={ref} className={`vague-maitrise ${grand ? "grand" : ""} ${taux === 0 ? "vide" : ""} ${plein ? "pleine" : ""}`}
         style={{ "--vague-couleur": couleur, "--vague-cote": cote ? `${cote}px` : "100%" }}>
      <img className="vague-gris" src={order.portrait} alt="" />
      <div className="vague-pleine" style={{ height: `${hauteur}%` }}>
        <img className="vague-couleur" src={order.portrait} alt="" />
        <div className="vague-teinte" />
      </div>
    </div>
  );
}

// ---------- La flamme vivante ----------
// UNE seule flamme pour la ligne du profil et le panneau : le contour au trait
// d'origine, un clipPath STATIQUE en silhouette (pose une fois, jamais anime),
// et trois couches pleines qui vacillent -- transform et opacity SEULEMENT,
// la regle de performance absolue du projet. Eteinte : couches masquees,
// contour gris, parfaitement immobile. remplissage : les couches remontent de
// sous la base une fois (cascade puis micro-rebond), et le vacillement suit.
// onRempli previent l'appelant quand le remplissage A ETE VU, pour qu'il ne
// rejoue pas a la prochaine ouverture.
const FLAMME_TRAIT = "M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z";
const FLAMME_MOYENNE = "M12 6.2c1.5 2 3.4 3.9 3.4 6.4a3.4 4.4 0 1 1-6.8 0c0-2.1 1.9-4.2 3.4-6.4z";
const FLAMME_COEUR = "M12 10c.9 1.3 1.9 2.3 1.9 3.8a1.9 2.4 0 1 1-3.8 0c0-1.3 1-2.5 1.9-3.8z";
let flammeClipCompteur = 0;
function FlammeVivante({ allumee, className, remplissage, onRempli, jours = 7 }) {
  // Un id de clip unique par instance : le profil et le panneau peuvent
  // montrer la flamme en meme temps sans se voler le clip.
  const clipIdRef = useRef("flamme-clip-" + (++flammeClipCompteur));
  // Un septieme par jour de serie (02/09) : la flamme au repos est remplie a
  // hauteur de la serie en cours, pleine des 7 jours. Le decalage est un
  // ETAT, pas une animation : custom property inline consommee par un
  // transform statique sur le groupe PARENT .flamme-niveau -- il survit a
  // .reduced-motion, et le vacillement des couches ENFANTS se compose avec
  // lui sans l ecraser. 19 : la hauteur utile de la silhouette (du sommet
  // vers y=3 a la base vers y=22 du viewBox). jours absent : pleine, comme
  // avant. Aucune regle de la Flamme ne change, c est un habillage.
  const fraction = Math.min(Math.max(jours || 0, 0), 7) / 7;
  const decalageNiveau = Math.round((1 - fraction) * 19 * 10) / 10;
  // Le remplissage se joue quand l'element est A L'ECRAN : on previent
  // l'appelant apres la fin de la cascade et du rebond (~1,2 s).
  useEffect(() => {
    if (!remplissage || !onRempli) return;
    const t = setTimeout(onRempli, 1400);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [remplissage]);
  return (
    <svg
      className={`flamme-vive ${allumee ? "allumee" : ""} ${allumee && remplissage ? "remplit" : ""} ${className || ""}`}
      viewBox="0 0 24 24"
      aria-hidden="true"
    >
      <defs>
        <clipPath id={clipIdRef.current}>
          <path d={FLAMME_TRAIT} />
        </clipPath>
      </defs>
      <g clipPath={`url(#${clipIdRef.current})`}>
        <g className="flamme-niveau" style={{ "--flamme-niveau": `${decalageNiveau}px` }}>
          <g className="flamme-remplissage">
            <path className="flamme-couche flamme-sombre" d={FLAMME_TRAIT} fill="#8a6a2c" />
            <path className="flamme-couche flamme-or" d={FLAMME_MOYENNE} fill="var(--gold)" />
            <path className="flamme-couche flamme-coeur" d={FLAMME_COEUR} fill="var(--gold-bright)" />
          </g>
        </g>
      </g>
      <path className="flamme-contour" d={FLAMME_TRAIT} fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function ComingSoonThumb({ order }) {
  const [peek, setPeek] = useState(false);
  const peekTimer = useRef(null);
  useEffect(() => () => clearTimeout(peekTimer.current), []);
  const revealBriefly = () => {
    setPeek(true);
    clearTimeout(peekTimer.current);
    peekTimer.current = setTimeout(() => setPeek(false), 1100);
  };
  // Dans la fenetre d'acces anticipe : plus de cadenas, portrait sans filtre.
  const devoile = ordreDevoile(order);
  return (
    <div
      className={`order-thumb-wrap teaser-wrap ${devoile ? "teaser-devoile" : ""} ${peek ? "teaser-peek" : ""}`}
      onPointerDown={revealBriefly}
    >
      <div className="teaser-aura" />
      <img className="thumb thumb-teaser" src={order.portrait} alt={nomOrdreAffiche(order)} />
      <div className="teaser-scan" />
      {!devoile && (<div className="lock-chip">
        <svg className="lock-icon" viewBox="0 0 24 24" fill="none">
          <path d="M6 10V7a6 6 0 0112 0v3" stroke="var(--gold-bright)" strokeWidth="2" strokeLinecap="round" fill="none" />
          <rect x="4" y="10" width="16" height="12" rx="2.5" fill="var(--gold-bright)" stroke="var(--gold)" strokeWidth="1" />
          <circle cx="12" cy="15" r="1.7" fill="#1b2138" />
          <rect x="11" y="16" width="2" height="3.5" rx="1" fill="#1b2138" />
        </svg>
      </div>)}
    </div>
  );
}

const TURN_SECONDS = 105; // durée du minuteur par tour (1 min 45)
// L'apercu des mains, entre amis, se referme seul au bout de ce delai. Sans cette borne,
// un joueur parti boire un cafe devant cet ecran se faisait declarer forfait par son ami
// (FORFAIT_APRES_S) sans avoir jamais vu le plateau.
const APERCU_MS = 20000;
// Minuteur du choix des Ordres, en ligne uniquement : sans lui, un joueur qui pose son
// telephone bloque l'autre sur un ecran d'attente. A l'echeance, la selection en cours
// est confirmee ; si elle est incomplete, deux Ordres sont tires au sort.
// 90 et non plus 60 : depuis que la Reserve existe, choisir ses Ordres c'est aussi
// preparer ce qu'on gardera de cote. Trente secondes de plus, a la demande du Commandant.
const ORDRES_SECONDS = 90;
const RESERVE_SECONDS = 30;                // le meme compte a rebours, pour la Reserve
// Passé de 60 à 105 s avec la main en éventail : les cartes ne sont plus toutes visibles
// d'un coup, il faut déployer chaque Ordre pour lire ses rangs avant de choisir. Une
// minute ne suffisait plus pour comparer sereinement.
const DRAFT_SECONDS = 15; // durée du minuteur par choix, en draft Confluence

// ---------- Tutoriel interactif ----------
function tc(top, right, bottom, left, opts = {}) {
  return {
    id: `tut-${top}-${right}-${bottom}-${left}-${Math.random().toString(36).slice(2, 7)}`,
    name: opts.name || "Recrue",
    icon: opts.icon || "⚔️",
    portrait: opts.portrait || "",
    orderKey: opts.orderKey || "",
    ability: opts.ability || "none",
    top, right, bottom, left,
    baseTop: top, baseRight: right, baseBottom: bottom, baseLeft: left,
  };
}

