// Les quatre facons de lire un nom. Chacune a SA liste de termes, passee par la meme
// reduction : « connard » ecrase en « conard » doit se chercher sous « conard ».
const VARIANTES_DE_LECTURE = [
  {},
  { leet: true, sansRepetitions: true },
  { sansChiffres: true, sansRepetitions: true },
  { leet: true, fondIL: true, sansRepetitions: true },
];
function reduireListe(liste, options) {
  const vus = new Set();
  for (const mot of liste) { const r = squeletteDuNom(mot, options); if (r) vus.add(r); }
  return [...vus];
}
// Un terme reduit a moins de quatre lettres ne discrimine plus rien : il se retrouverait
// par hasard dans des noms honnetes. On l abandonne plutot que de refuser a tort — sauf
// une poignee de sigles dont aucun mot francais ni anglais ne porte les lettres a la
// suite, verifies un par un.
const SIGLES_SURS = new Set(["fdp", "kys", "kkk", "zog"]);
const TERMES_PARTOUT = VARIANTES_DE_LECTURE.map((o) =>
  reduireListe(NOMS_INTERDITS_PARTOUT, o).filter((t) => t.length >= 4 || SIGLES_SURS.has(t)));

// Codes chiffres a connotation extremiste. Les codes ISOLES (88, 14, 18) restent permis :
// une annee de naissance, un age, un numero de maillot. Seules les combinaisons sans
// ambiguite tombent. On les cherche en repliant les lettres du nom VERS les chiffres
// qu elles imitent — « 14BB » et « lABB » se lisent 1488 — plutot que l inverse.
const CODES_INTERDITS = ["1488", "8814", "combat18", "combat28", "14mots", "14words"];
const VERS_CHIFFRES = { o: "0", i: "1", l: "1", z: "2", e: "3", a: "4", s: "5", t: "7", b: "8", g: "9" };
function chiffrerLeNom(nom) {
  return [...squeletteDuNom(nom, {})].map((c) => VERS_CHIFFRES[c] || c).join("");
}
const TERMES_ENTIERS = VARIANTES_DE_LECTURE.map((o) => new Set(reduireListe([...NOMS_INTERDITS_ENTIERS], o)));
const PERMIS_REDUITS = VARIANTES_DE_LECTURE.map((o) => reduireListe(NOMS_TOUJOURS_PERMIS, o));

// Un terme trouve peut etre innocent : « salope » se trouve dans « salopette ». On regarde
// si un nom honnete occupe exactement cette place ; si oui, la trouvaille ne compte pas.
function trouvailleExcusee(lecture, terme, position, permis) {
  for (const mot of permis) {
    if (!mot.includes(terme)) continue;
    let p = lecture.indexOf(mot);
    while (p !== -1) {
      if (position >= p && position + terme.length <= p + mot.length) return true;
      p = lecture.indexOf(mot, p + 1);
    }
  }
  return false;
}

// Ce nom est-il refusable ? Avec durSeulement, on s'en tient a la liste dure : c'est la
// forme employee pour juger un nom DEJA choisi, la ou un refus retire son nom a quelqu'un
// sans qu'il ait rien demande. La liste large ne sert qu'a la saisie et a l'affichage, la
// ou un refus se corrige ou se remplace sans rien couter au joueur.
const JUGEMENTS = new Map(); // les memes deux noms sont juges a chaque instantane recu
function nomRefuse(nom, durSeulement) {
  const propre = nettoyerPseudo(nom);
  if (!propre) return false;
  const cle = (durSeulement ? "d:" : "l:") + propre;
  const connu = JUGEMENTS.get(cle);
  if (connu !== undefined) return connu;
  const verdict = jugerNom(propre, durSeulement);
  if (JUGEMENTS.size > 400) JUGEMENTS.clear();
  JUGEMENTS.set(cle, verdict);
  return verdict;
}
const PARURE = /^[x_.0-9-]+|[x_.0-9-]+$/g;
function noyauDuNom(lecture) {
  const noyau = lecture.replace(PARURE, "");
  return noyau.length >= 3 && noyau !== lecture ? noyau : null;
}

function jugerNom(propre, durSeulement) {
  const chiffre = chiffrerLeNom(propre);
  for (const code of CODES_INTERDITS) if (chiffre.includes(code)) return true;
  for (let i = 0; i < VARIANTES_DE_LECTURE.length; i++) {
    const lecture = squeletteDuNom(propre, VARIANTES_DE_LECTURE[i]);
    if (!lecture) continue;
    // La lecture repliee se relit aussi a l'envers : « reltih » cache « hitler ».
    const vues = i === 1 ? [lecture, [...lecture].reverse().join("")] : [lecture];
    for (const vue of vues) {
      for (const terme of TERMES_PARTOUT[i]) {
        let p = vue.indexOf(terme);
        while (p !== -1) {
          if (!trouvailleExcusee(vue, terme, p, PERMIS_REDUITS[i])) return true;
          p = vue.indexOf(terme, p + 1);
        }
      }
    }
    if (durSeulement) continue;
    const permis = PERMIS_REDUITS[i];
    const formes = [lecture, lecture.replace(/[0-9]+$/, ""), noyauDuNom(lecture)].filter(Boolean);
    if (formes.some((f) => permis.includes(f))) continue;
    if (formes.some((f) => TERMES_ENTIERS[i].has(f))) return true;
  }
  return false;
}

// Le nom d'un ADVERSAIRE, tel qu'on accepte de le montrer. C'est ici que se joue la vraie
// protection : celui qui triche maitrise son propre appareil, jamais celui d'en face. Le
// filtre pose a la saisie n'engage que les joueurs honnetes ; celui-ci s'execute chez la
// personne qu'il protege, hors de portee de l'autre. Il remet aussi le nom recu en FORME,
// alors qu'il arrivait jusqu'ici tel quel : un client modifie pouvait envoyer cinq cents
// caracteres ou des espaces et defaire la mise en page de l'etiquette de camp.
// Renvoyer "" suffit : nomDuCamp retombe alors sur « Adversaire », deja ecrit.
// Volontairement MUET. Les deux ecrans cessent d'afficher la meme chose, et c'est le but :
// l'auteur du nom continue de le voir chez lui et n'apprend jamais qu'il est masque en
// face, donc n'a aucun moyen de chercher a tatons la formule qui passerait.
function pseudoAffichable(brut) {
  // Ce qui arrive de Firestore n est pas garanti etre une chaine : un client modifie peut
  // y avoir depose un nombre, un tableau, un objet. Tout ce qui n est pas du texte est
  // traite comme une absence de nom.
  if (typeof brut !== "string") return "";
  const propre = nettoyerPseudo(brut);
  if (!propre || nomRefuse(propre)) return "";
  return propre;
}

function lirePseudo() {
  try {
    const v = localStorage.getItem(CLE_PSEUDO);
    // Liste dure seulement : elargir ici retirerait son nom, au demarrage et sans un mot,
    // a un joueur qui l'a porte cent parties. Le refus renvoie "" et l'ecran de nommage
    // reparait — les statistiques, elles, vivent a part et ne bougent pas.
    if (v !== null) { const nom = nettoyerPseudo(v); return nomRefuse(nom, true) ? "" : nom; }
  } catch (e) { /* stockage bloque : on retombe sur la memoire */ }
  return pseudoMemoire || "";
}

function ecrirePseudo(nom) {
  pseudoMemoire = nom;
  try { localStorage.setItem(CLE_PSEUDO, nom); } catch (e) { /* non persiste cette session */ }
}

// ---------- Maitrise des Ordres ----------
// Un Ordre se maitrise en le jouant : 6 500 parties pour en faire le tour. La progression
// se lit en pourcentage de ce total, et franchit sept rangs en chemin. Les paliers ne
// sont pas espaces egalement : les premiers viennent vite, pour que l'on sente tout de
// suite que l'on avance, les derniers se meritent — 6 500 parties, c'est une vie de jeu.
const MAITRISE_PARTIES_MAX = 6500;
const MAITRISE_RANGS = [
  { nom: "Recrue", min: 0 },
  { nom: "Initié", min: 25 },
  { nom: "Disciple", min: 100 },
  { nom: "Vétéran", min: 350 },
  { nom: "Maître", min: 1000 },
  { nom: "Archonte", min: 2500 },
  { nom: "Éminence", min: MAITRISE_PARTIES_MAX },
];
// Couleur propre a chaque Ordre, pour la vague qui monte dans son portrait. Les Ordres
// qui ont un chapitre d'Histoire reprennent la teinte de ce chapitre ; les deux autres
// recoivent la leur ici : l'or des Dores, le cyan des Chimeres.
const MAITRISE_COULEURS = {
  eveil: "rgba(232,200,119,0.85)",
  cendres: "rgba(255,120,40,0.85)",
  percee: "rgba(200,220,255,0.9)",
  portee: "rgba(110,200,90,0.85)",
  devoreuse: "rgba(80,160,255,0.7)",
  mue: "rgba(75,201,201,0.8)",
  poison: "rgba(120,220,80,0.7)",
  guardian: "rgba(170,180,200,0.8)",
  scribes: "rgba(205,120,255,0.75)",
  maudits: "rgba(150,80,220,0.75)",
  geolier: "rgba(180,180,180,0.6)",
};

function maitriseOrdre(stats, cle) {
  // Number() : un vieux stockage pourrait porter autre chose qu'un nombre, et un NaN
  // s'afficherait tel quel ("NaN %").
  const parties = Math.max(0, Number((stats && stats.orderPlays && stats.orderPlays[cle]) || 0) || 0);
  const taux = Math.min(1, parties / MAITRISE_PARTIES_MAX);
  let rang = 0;
  for (let i = 0; i < MAITRISE_RANGS.length; i++) if (parties >= MAITRISE_RANGS[i].min) rang = i;
  const suivant = MAITRISE_RANGS[rang + 1] || null;
  return {
    parties,
    taux,
    // 1 partie = deja 1 %, pas 0 ; et 100 % est reserve au dernier rang : arrondir
    // 6 499 parties a 100 % alors qu'on est encore Archonte se contredisait a l'ecran.
    pourcent: parties === 0 ? 0 : parties >= MAITRISE_PARTIES_MAX ? 100 : Math.min(99, Math.max(1, Math.round(taux * 100))),
    rang: MAITRISE_RANGS[rang],
    numero: rang + 1,
    suivant,
    manque: suivant ? suivant.min - parties : 0,
  };
}

// Version du compteur orderPlays. Avant la page de maitrise, il additionnait les Ordres
// des DEUX camps, les miens et ceux d'en face : impossible, apres coup, d'en retirer la
// part de l'adversaire. On l'oublie donc une fois pour toutes, plutot que d'afficher
// "Initie" sur un Ordre jamais tenu en main. A incrementer si son sens change encore.
const MAITRISE_VERSION = 1;
// L'Ordre le plus joue, pour le medaillon de la ligne epinglee du Pantheon. Rend null
// tant qu'aucune partie n'est jouee : mieux vaut un disque vide qu'un Ordre au hasard.
function ordreLePlusJoue(stats) {
  const parties = (stats && stats.orderPlays) || {};
  let cle = null, max = 0;
  for (const o of ORDERS) {
    const n = Math.max(0, Number(parties[o.key] || 0) || 0);
    if (n > max) { max = n; cle = o.key; }
  }
  return cle;
}

// ---------- La Reserve et la Mort Subite ----------
// Le camp qui COMMENCE part avec un handicap : c'est le second qui pose la derniere
// carte, en sachant tout. Mesure faite sur 14 500 parties simulees avec ce moteur meme
// (voir outils-equilibrage/) : il ne gagne que 40 % des parties des qu'on sait jouer.
//
// Un point d'avance ne peut rien y faire. Seize cartes sont posees, donc l'ecart de
// cartes est toujours PAIR : +1 et +2 donnent exactement le meme resultat (40 %), +3
// saute a 58 %. Aucun nombre entier ne tombe pres de 50.
//
// D'ou cette regle : DEUX points d'avance, ce qui transforme la defaite la plus
// frequente du premier joueur -- deux cartes de retard, environ 17 % des parties -- en
// egalite parfaite ; et cette egalite se joue au lieu d'etre donnee. Chaque Commandant a
// choisi AVANT la partie deux cartes de Reserve : il les pose sur les cases restees
// vides, et l'on recompte. Rien n'est tire au sort au moment le plus tendu du duel.
const RESERVE_TAILLE = 2;
const MORT_SUBITE_RONDES_MAX = 2;
// La version affichee au bas des Reglages. A BOUGER a chaque livraison notable : c'est
// elle qui permet de savoir en un regard si un telephone est a jour, au lieu de deviner
// a travers trois messages. Le format dit la date et l'heure de la livraison.
const VERSION_AFFICHEE = "29 août · 15h";

// L'avance du premier joueur, dans TOUS les modes. Deux points, et non un : a un point
// la somme etait impaire (16 + 1 = 17) et l'egalite parfaite restait impossible, donc la
// Mort Subite ne pouvait jamais s'ouvrir. C'est justement cette egalite qu'on veut --
// elle se joue, au lieu d'etre donnee.
const AVANCE_DU_PREMIER = 2;

// La force brute d'une carte, pour que l'Echo compose sa Reserve sans reflechir
// longtemps : il garde ses deux cartes aux rangs les plus hauts.
function forceDeCarte(c) { return (c.top || 0) + (c.right || 0) + (c.bottom || 0) + (c.left || 0); }
// UNE carte par Ordre, comme le joueur : on garde la plus forte de chaque Ordre present.
// Sans cette regle l'Echo emportait deux fois sa meilleure carte, ce qui lui donnait une
// Reserve que le joueur n'a pas le droit de composer.
function reserveAutomatique(main) {
  const parOrdre = new Map();
  for (const c of main) {
    const tenante = parOrdre.get(c.ability);
    if (!tenante || forceDeCarte(c) > forceDeCarte(tenante)) parOrdre.set(c.ability, c);
  }
  return [...parOrdre.values()]
    .sort((a, b) => forceDeCarte(b) - forceDeCarte(a))
    .slice(0, RESERVE_TAILLE)
    .map((c, i) => ({ ...c, id: c.id + "-reserve-" + i }));
}

