const DOS_DEFAUT = "blason";
// Le dos de l Echo (01/09). En face, c etait le Blason offert -- exactement
// celui que le joueur a a ses debuts, si bien que les deux camps se
// ressemblaient trait pour trait. L Echo prend donc un dos du catalogue,
// l Obsidienne, qui s achete en pieces.
// Il ne le POSSEDE pas : rien ne se debloque, rien ne se verse, aucune
// possession n est touchee. C est un decor, seulement ce qu on voit en face.
const DOS_ECHO = "obsidienne";
function dosDe(cle) { return DOS_CARTES.find((d) => d.cle === cle) || DOS_CARTES[0]; }
// Les deux variables que le dos lit. Le dos est desormais un MOTIF PUR (03/09) :
// plus de portrait d Ordre en medaillon au centre. Il ne disait rien qu on ne
// sache deja -- en Mort Subite, les cartes de Reserve sortent dans l ordre
// compose avant la partie (reserveBleue[mortSubiteRonde]), le joueur ne choisit
// jamais laquelle poser : le portrait n etait qu un rappel.
// image : quand une entree en porte une, elle REMPLACE la recette de degrades.
// Le degrade sombre reste dessous, en deuxieme couche : un fichier absent laisse
// une carte propre au lieu d un trou.
// anneau et socle ne sont plus poses : ils ne servaient qu au medaillon central,
// disparu avec lui. Les champs restent au catalogue, prets si un sceau revient.
function variablesDos(cle) {
  const d = dosDe(cle);
  return {
    "--dos-fond": d.image
      ? `url("${d.image}") center / cover no-repeat, linear-gradient(160deg, #2a2138 0%, #14101d 100%)`
      : d.fond,
    "--dos-bord": d.bord,
  };
}
function plateauDe(cle) { return PLATEAUX.find((p) => p.cle === cle) || PLATEAUX[0]; }
// Les cinq variables que .table et .cell lisent. Posees sur la dalle, elles descendent
// d'elles-memes jusqu'aux cases : c'est de l'heritage, pas une regle par case.
function variablesPlateau(cle) {
  const p = plateauDe(cle);
  return {
    "--plateau-dalle": p.dalle, "--plateau-bord": p.bord,
    "--plateau-case": p.case, "--plateau-case-bord": p.caseBord,
    "--plateau-lueur": p.lueur,
  };
}

// La feuille de partage du telephone n'existe que sur origine securisee (https, ou
// localhost). Evaluee UNE fois : elle ne va pas apparaitre en cours de route, et chaque
// bouton d'envoi ne se montre que si elle existe -- un bouton d'envoi qui copie est un
// bouton qui ment.
const PARTAGE_NATIF = typeof navigator !== "undefined" && !!navigator.share;

// Copier un texte, partout -- y compris hors HTTPS. navigator.clipboard n'existe que sur
// origine securisee (https ou localhost) : sur un telephone qui ouvre http://192.168.x.x
// il vaut undefined, et l'appeler levait une TypeError avalee par le try/catch appelant.
// D'ou le repli sur document.execCommand("copy"), deprecie mais seul chemin praticable
// sur un reseau local. Rend true si le texte est bien parti.
async function copierTexte(texte) {
  try {
    if (typeof navigator !== "undefined" && navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(texte);
      return true;
    }
  } catch (e) { /* refuse ou indisponible : on tente le repli */ }
  try {
    const zone = document.createElement("textarea");
    zone.value = texte;
    // Hors ecran mais SELECTIONNABLE : display:none ou visibility:hidden empechent la
    // selection, donc la copie. readOnly evite au clavier du telephone de surgir.
    zone.setAttribute("readonly", "");
    zone.style.cssText = "position:fixed;top:0;left:-9999px;opacity:0";
    document.body.appendChild(zone);
    zone.select();
    zone.setSelectionRange(0, texte.length); // iOS ignore select() seul
    const ok = document.execCommand("copy");
    document.body.removeChild(zone);
    return !!ok;
  } catch (e) { return false; }
}

// ---------- Ligues & Héros ----------
// Barème compétitif : +30 trophées par victoire, -15 par défaite, jamais en dessous de 0.
// Conséquence à connaître : le point d'équilibre est à 33 % de victoires. En dessous, le
// joueur recule ; au-dessus, il progresse. Un joueur à 50 % gagne 7,5 trophées par partie
// en moyenne, soit environ 333 parties pour atteindre Légende.
// Le bilan ne s'affiche pas d'un bloc : il MONTE, de un jusqu'a sa valeur. Court, parce
// qu'il accompagne la fin de partie sans la retenir. Il part apres l'entree du badge, le
// temps qu'il ait fini de se poser.
// Le compte du bilan : de 1 jusqu'au total, en presque trois secondes -- lent, a la
// demande du Commandant, et long a dessein : meme si l'entree du panneau se decale d'une
// seconde sur un appareil, l'essentiel du compte reste sous les yeux.
const BILAN_COMPTE_MS = 2800;
// Le DEPART du compte, depuis l'ouverture de la ceremonie : il doit tomber APRES le
// lever de rideau de la recap, invisible avant. Victoire : cer-monte finit a
// 1,75 + 0,65 s. Defaite : buttonFadeUp finit a 1,5 + 0,6 s. Partir avant, c'est compter
// dans le noir -- trois signalements du Commandant pour l'apprendre.
const BILAN_DEPART_VICTOIRE_MS = 2500;
const BILAN_DEPART_DEFAITE_MS = 2200;
const TROPHEES_VICTOIRE = 30;
const TROPHEES_DEFAITE = -15;

