// ---------- Arenes deja vues ouvertes ----------
// Au tout premier lancement la cle est absente : on considere alors comme "deja vues"
// toutes les arenes ouvertes du moment. Sans cela, un joueur qui installe le jeu verrait
// le Bronze se deverrouiller ceremonieusement alors qu'il ne l'a jamais eu verrouille.
const CLE_ARENES_VUES = "emprise-arenes-vues";
function lireArenesVues() {
  try {
    const v = localStorage.getItem(CLE_ARENES_VUES);
    return v ? JSON.parse(v) : null; // null : jamais ecrit
  } catch (e) { return null; }
}
function ecrireArenesVues(noms) {
  try { localStorage.setItem(CLE_ARENES_VUES, JSON.stringify(noms)); } catch (e) { /* tant pis */ }
}

// ---------- Historique des parties ----------
// Les 3 dernières parties terminées, la plus récente en premier. Volontairement
// minuscule (3 entrées, quelques champs) : un vrai journal viendra avec les profils.
const HISTORIQUE_MAX = 3;
function lireHistorique() {
  try {
    const brut = localStorage.getItem("emprise-historique");
    const liste = brut ? JSON.parse(brut) : [];
    if (!Array.isArray(liste)) return [];
    // Classé uniquement pour l'instant. Le filtre sert aussi de nettoyage : les entrees
    // enregistrees avant cette regle, qui n'ont pas le marqueur, sont ecartees.
    return liste.filter((e) => e && e.classee).slice(0, HISTORIQUE_MAX);
  } catch (e) { return []; }
}
function ecrireHistorique(entree) {
  const liste = [entree, ...lireHistorique()].slice(0, HISTORIQUE_MAX);
  try { localStorage.setItem("emprise-historique", JSON.stringify(liste)); } catch (e) { /* non persisté */ }
  return liste;
}
// "il y a 5 min" plutôt qu'une date brute : sur 3 parties récentes, la fraîcheur
// relative se lit mieux qu'un horodatage.
function ilYa(t) {
  const s = Math.max(0, Math.floor((Date.now() - t) / 1000));
  if (s < 60) return "à l'instant";
  const min = Math.floor(s / 60);
  if (min < 60) return `il y a ${min} min`;
  const h = Math.floor(min / 60);
  if (h < 24) return `il y a ${h} h`;
  const j = Math.floor(h / 24);
  return j === 1 ? "hier" : `il y a ${j} jours`;
}

let memoryStats = null; // repli en mémoire si aucun stockage durable n'est disponible

async function readStatsRaw() {
  if (typeof window !== "undefined" && window.storage && window.storage.get) {
    try {
      const res = await window.storage.get("emprise-stats");
      return res && res.value != null ? res.value : null;
    } catch (e) {
      return null; // clé absente ou stockage indisponible
    }
  }
  try {
    if (typeof localStorage !== "undefined") {
      const v = localStorage.getItem("emprise-stats");
      if (v != null) return v;
    }
  } catch (e) { /* stockage bloqué */ }
  return memoryStats;
}

async function writeStatsRaw(str) {
  if (typeof window !== "undefined" && window.storage && window.storage.set) {
    try { await window.storage.set("emprise-stats", str); return; } catch (e) { /* on tente la suite */ }
  }
  try {
    if (typeof localStorage !== "undefined") { localStorage.setItem("emprise-stats", str); return; }
  } catch (e) { /* stockage bloqué */ }
  memoryStats = str;
}

async function loadStats() {
  const raw = await readStatsRaw();
  if (!raw) return { ...DEFAULT_STATS };
  try {
    const parsed = JSON.parse(raw);
    // Compteur d'une version anterieure (ou sans version) : il melangeait les Ordres d'en
    // face aux miens, on repart de zero. Les autres stats sont gardees telles quelles.
    const orderPlays = parsed.maitriseVersion === MAITRISE_VERSION ? (parsed.orderPlays || {}) : {};
    // Le tally des paires (titre L Alchimiste), assaini : une cle est deux
    // Ordres connus, tries, joints par + ; le compte est un entier borne.
    // Tout le reste est jete. Une vieille sauvegarde sans le champ charge
    // avec un tally vide, sans erreur.
    const paires = {};
    if (parsed.paires && typeof parsed.paires === "object") {
      for (const [cle, n] of Object.entries(parsed.paires)) {
        const morceaux = String(cle).split("+");
        const valide = morceaux.length === 2
          && morceaux.every((k) => ORDERS.some((o) => o.key === k))
          && [...morceaux].sort().join("+") === cle;
        if (valide && Number.isFinite(n)) paires[cle] = Math.max(0, Math.min(1000000, Math.floor(n)));
      }
    }
    return { ...DEFAULT_STATS, ...parsed, orderPlays, combos: parsed.combos || {}, paires, maitriseVersion: MAITRISE_VERSION };
  } catch (e) {
    return { ...DEFAULT_STATS };
  }
}

// orderKeys : liste des clés d'Ordre (chaînes) réellement utilisées cette partie.
// trophyGain : variation de trophées de cette partie (0 hors multijoueur en ligne).
// Seules les parties en ligne comptent pour le classement ; les Échos et le jeu local ne
// rapportent rien. La valeur peut être négative (défaite en ligne).
// Renvoie les stats mises à jour pour rafraîchir l'état React.
// comboKeys : combos reconnus pendant cette partie (liste vide si la partie ne compte pas
// pour le profil — bac a sable, Mode Histoire, duel local, ou annulation utilisee).
// compteAuProfil : dit si cette partie entre dans le denominateur du profil. Une partie
// hors-profil ne doit NI compter ses combos NI gonfler le total, sinon le taux baisserait.
// monCamp : le camp que J'AI tenu cette partie (null en duel local, ou les deux joueurs
// sont humains et aucune victoire n'est "la mienne"). blueWins et redWins comptent les
// camps du PLATEAU : une egalite etant impossible, leur somme vaut toujours gamesPlayed
// et ne peut donc pas servir de compteur personnel — le profil affichait ainsi autant de
// "victoires" que de parties jouees, defaites comprises.
// releveSucces (01/09) : ce que la partie a produit, pour les medaillons de
// succes -- { resonances, ondes, mortSubite }. Un objet en queue plutot qu un
// treizieme parametre positionnel : la liste est deja longue, et un champ de
// plus s y ajoutera sans compter les virgules.
async function recordGameStats(winner, orderKeys, trophyGain = 0, comboKeys = [], compteAuProfil = false, monCamp = null, partieHistoire = false, difficulteEcho = null, ecartScore = null, mesOrdres = null, partieEcourtee = false, adversaireClasse = null, releveSucces = null, classiqueEnLigne = false) {
  const stats = await loadStats();
  stats.gamesPlayed += 1;
  if (monCamp && winner === monCamp) stats.mesVictoires = (stats.mesVictoires || 0) + 1;
  if (compteAuProfil) {
    stats.combosParties = (stats.combosParties || 0) + 1;
    if (!stats.combos) stats.combos = {};
    comboKeys.forEach((key) => { stats.combos[key] = (stats.combos[key] || 0) + 1; });
    // Le tally des paires jouees (cle triee, "cendres+poison"), pour le titre
    // L Alchimiste. Ecrit ICI seulement, et PAS retroactif : les parties
    // d avant ce champ n y figurent pas. mesOrdres est la liste de MES deux
    // Ordres -- orderKeys, lui, mele les deux camps et ne peut pas servir.
    if (Array.isArray(mesOrdres) && mesOrdres.length === 2) {
      if (!stats.paires) stats.paires = {};
      const clePaire = [...mesOrdres].sort().join("+");
      stats.paires[clePaire] = (stats.paires[clePaire] || 0) + 1;
    }
  }
  if (winner === "blue") stats.blueWins += 1;
  else if (winner === "red") stats.redWins += 1;
  orderKeys.forEach((key) => {
    stats.orderPlays[key] = (stats.orderPlays[key] || 0) + 1;
  });
  // Plancher à 0 : une série de défaites ne peut jamais faire passer le total en négatif.
  stats.trophies = Math.max(0, (stats.trophies || 0) + trophyGain);
  await writeStatsRaw(JSON.stringify(stats));
  // La rencontre classee du jour se compte ICI, partie TERMINEE -- declassee
  // et abandon compris : la 5e et la 6e restent amicales jusqu a demain. Le
  // forfait d avant-match ne passe jamais par cette fonction : une partie
  // jamais jouee ne brule pas de rencontre.
  if (adversaireClasse) await compterRencontre(adversaireClasse, classiqueEnLigne ? "classique" : "classe");
  // ---------- L'XP de la partie ----------
  // La MEME porte que le profil (compteAuProfil et monCamp), plus l'Histoire par son
  // signal dedie : le bac a sable, le mode test, les duels locaux et le bot-contre-bot
  // ne donnent rien sans qu'on ait rien a ajouter. La Confluence suit la porte du
  // profil : exclue aujourd'hui, comme des combos. L'egalite n'arrive jamais (elle donne
  // la victoire au second joueur) ; son bareme attend le jour ou elle existera.
  if (monCamp && (compteAuProfil || partieHistoire)) {
    const victoire = winner === monCamp;
    const classee = trophyGain !== 0;
    // L'ecart de score AFFICHE au joueur, assaini : un entier d'au moins 1,
    // sinon nul -- et nul veut dire base SANS marge, jamais un ecart invente
    // (fin forcee, vieil appelant). La marge est plafonnee : au-dela, l'ecart
    // en dit plus sur la faiblesse d'en face que sur le talent du vainqueur.
    const ecart = Number.isFinite(ecartScore) && ecartScore >= 1 ? Math.floor(ecartScore) : null;
    const marge = ecart === null ? 0 : Math.min(ecart, PIECES_PARTIES.margePlafond);
    let montant;
    let pieces;
    let piecesDetail;
    if (victoire && classee) {
      // La ligue APRES la partie : celle ou le joueur vient d'arriver.
      const indexLigue = Math.max(0, LEAGUES.indexOf(getLeague(stats.trophies)));
      // Partie ecourtee (fin forcee, plateau presque vide) : la moitie de la
      // base, arrondie au superieur, SANS part de ligue. Les pieces, elles,
      // passent par le meme bareme avec l'ecart nul transmis par l'appelant.
      montant = partieEcourtee
        ? Math.ceil(XP_PARTIES.victoireClasseBase / 2)
        : XP_PARTIES.victoireClasseBase + XP_PARTIES.victoireClasseParLigue * indexLigue;
      const base = PIECES_PARTIES.classe.baseVictoire + PIECES_PARTIES.classe.parLigue * indexLigue;
      piecesDetail = { base, marge: PIECES_PARTIES.classe.parEcart * marge, prime: 0, histoire: 0 };
    } else if (victoire && classiqueEnLigne) {
      // La Partie classique (01/09) : le bareme du Classe, a la moitie. Elle
      // apparie deux humains comme lui, elle en garde donc l echelle -- mais
      // elle ne coute ni ne rapporte un seul trophee, et son butin ne doit pas
      // valoir celui d une partie ou l on risque son rang.
      // La moitie se prend sur CHAQUE part, a l entier inferieur, pour que
      // l ecran de fin garde son detail. Le plancher d une piece garantit
      // qu une victoire ne rapporte jamais rien.
      const indexLigue = Math.max(0, LEAGUES.indexOf(getLeague(stats.trophies)));
      const pleinBase = PIECES_PARTIES.classe.baseVictoire + PIECES_PARTIES.classe.parLigue * indexLigue;
      const pleinMarge = PIECES_PARTIES.classe.parEcart * marge;
      let demiBase = Math.floor(pleinBase / 2);
      const demiMarge = Math.floor(pleinMarge / 2);
      if (demiBase + demiMarge < 1) demiBase = 1;
      piecesDetail = { base: demiBase, marge: demiMarge, prime: 0, histoire: 0 };
      // L XP suit le chemin des parties non classees, inchange : la mission ne
      // portait que sur les pieces, et la table de l Echo est celle que toute
      // partie sans trophee emprunte deja.
      montant = partieEcourtee
        ? Math.ceil(XP_PARTIES.victoireEcho.intermediaire / 2)
        : XP_PARTIES.victoireEcho.intermediaire;
    } else if (victoire) {
      // L'Histoire est un combat de bot comme un autre : meme table, plus sa prime.
      const table = XP_PARTIES.victoireEcho;
      const duBot = table[difficulteEcho] != null ? table[difficulteEcho] : table.intermediaire;
      // Ecourtee (amicale en ligne seulement : le hors-ligne ne force jamais
      // de fin) : la moitie de la base de la table, arrondie au superieur.
      montant = partieEcourtee
        ? Math.ceil(duBot / 2)
        : duBot + (partieHistoire ? XP_PARTIES.bonusHistoire : 0);
      const tableP = PIECES_PARTIES.echo.baseVictoire;
      const base = tableP[difficulteEcho] != null ? tableP[difficulteEcho] : tableP.intermediaire;
      piecesDetail = { base, marge: PIECES_PARTIES.echo.parEcart * marge, prime: 0,
                       histoire: partieHistoire ? PIECES_PARTIES.bonusHistoire : 0 };
    }
    else if (classee) {
      montant = XP_PARTIES.defaiteClassee;
      piecesDetail = { base: PIECES_PARTIES.classe.baseDefaite, marge: 0,
                       prime: ecart === 1 ? PIECES_PARTIES.classe.primeDefaiteSerree : 0, histoire: 0 };
    }
    else {
      montant = XP_PARTIES.defaite;
      piecesDetail = { base: PIECES_PARTIES.echo.baseDefaite, marge: 0,
                       prime: ecart === 1 ? PIECES_PARTIES.echo.primeDefaiteSerree : 0, histoire: 0 };
    }
    pieces = piecesDetail.base + piecesDetail.marge + piecesDetail.prime + piecesDetail.histoire;
    const bilan = await gagnerXp(montant, pieces);
    // Pose APRES l'ecriture des stats : ce champ voyage vers l'ecran de fin par le
    // setStats de l'appelant, mais ne se sauvegarde jamais. Le detail du versement
    // (base, marge, prime, Histoire) part avec lui : l'ecran de fin doit dire
    // POURQUOI 90 plutot que 45. Et une victoire ecourtee le dit aussi.
    stats.xpDePartie = { ...bilan, piecesDetail, partieEcourtee: partieEcourtee && victoire };
    // ---------- La Flamme quotidienne ----------
    // Le MEME signal que l'XP classee (classee, soit trophyGain non nul), et la
    // porte du profil en plus : Histoire, Echos, Confluence, tournois solo et
    // bac a sable ne la nourrissent jamais. La premiere partie classee du jour
    // seulement -- nourrirFlamme refuse d'elle-meme un second jour identique.
    let flammePleine = false;
    if (classee && compteAuProfil) {
      const feu = await nourrirFlamme();
      if (feu.jourNouveau) {
        stats.xpDePartie = { ...stats.xpDePartie, flamme: { jour: feu.flamme.serie, pieces: feu.piecesVersees } };
      }
      // La Flamme pleine, c est SEPT JOURS de serie -- un duel classe par jour,
      // sept jours d affilee. Ce n est pas sept parties dans la journee :
      // nourrirFlamme refuse d elle-meme un second jour identique.
      flammePleine = (feu.flamme.serie || 0) >= FLAMME_PARTS;
    }
    // ---------- L'Etendard de l'Echo ----------
    // Premiere victoire en partie LIBRE contre un Echo de cette difficulte :
    // son Etendard se gagne. Le signal histoire/libre est EXACTEMENT celui de
    // l'XP ci-dessus (l'Histoire et le classe s'excluent d'eux-memes), le bac
    // a sable et la Confluence restent dehors par la porte du profil. Pas de
    // retroactif : l'historique par difficulte n'existe pas. Le champ
    // banniereDebloquee voyage vers l'ecran de fin, jamais vers la sauvegarde
    // (il est pose apres writeStatsRaw, comme xpDePartie).
    if (victoire && !classee && !partieHistoire && compteAuProfil && difficulteEcho) {
      const etendard = BANNIERES.find((x) => x.source === "echo" && x.difficulte === difficulteEcho);
      if (etendard) {
        const res = await possederBanniere(etendard.cle, false);
        if (res.ajoutee) stats.banniereDebloquee = etendard.cle;
      }
    }
    // ---------- Le medaillon d un Ordre (03/09) ----------
    // Sa maitrise atteint le rang Disciple : son medaillon se gagne. Le seuil
    // est lu dans MAITRISE_RANGS, jamais recopie. On passe les onze en revue
    // plutot que les seuls Ordres de cette partie : c est aussi bon marche, et
    // cela rattrape d office les Ordres deja au-dela du seuil avant que le
    // systeme n existe -- il serait absurde qu un joueur a trois cents parties
    // de Gardiens attende la trois-cent-unieme. possederMedaillon jure de son
    // cote qu on ne le donne jamais deux fois. Le champ medaillonDebloque
    // voyage vers l ecran de fin, jamais vers la sauvegarde.
    const seuil = medaillonRang().min;
    const gagne = async (cle) => {
      const res = await possederMedaillon(cle, false);
      if (res.ajoutee && !stats.medaillonDebloque) stats.medaillonDebloque = cle;
    };
    for (const md of MEDAILLONS) {
      if (md.source !== "ordre") continue;
      if (maitriseOrdre(stats, md.ordre).parties < seuil) continue;
      await gagne(md.cle);
    }
    // ---------- Les medaillons de SUCCES (01/09) ----------
    // Des compteurs PASSIFS : ils observent la partie qui vient de finir et ne
    // changent rien a son deroulement. Les Resonances et les Ondes viennent du
    // releve des quetes, qui les comptait deja coup par coup -- rien de neuf
    // dans le moteur, on ne fait que cumuler. Les seuils vivent au catalogue,
    // jamais recopies ici.
    const rel = releveSucces || {};
    stats.resonancesTotal = (stats.resonancesTotal || 0) + Math.max(0, Math.floor(rel.resonances || 0));
    stats.ondesTotal = (stats.ondesTotal || 0) + Math.max(0, Math.floor(rel.ondes || 0));
    // Les victoires par Ordre, jumelles d orderPlays : mesOrdres est la liste
    // de MES deux Ordres, la seule qui vaille -- orderKeys mele les deux camps.
    if (victoire && Array.isArray(mesOrdres)) {
      if (!stats.orderWins) stats.orderWins = {};
      [...new Set(mesOrdres)].forEach((k) => { stats.orderWins[k] = (stats.orderWins[k] || 0) + 1; });
    }
    const seuilDe = (cle) => (medaillonDeCle(cle) || {}).seuil || 0;
    if (flammePleine) await gagne("flamme");
    if (victoire && rel.mortSubite) await gagne("mort-subite");
    if (stats.resonancesTotal >= seuilDe("resonance")) await gagne("resonance");
    if (stats.ondesTotal >= seuilDe("onde")) await gagne("onde");
    if (ORDERS.filter((o) => isOrderAvailable(o)).every((o) => ((stats.orderWins || {})[o.key] || 0) > 0)) {
      await gagne("pantheon");
    }
  }
  return stats;
}

// L'unique porte d'entree de l'XP : les parties aujourd'hui, les quetes demain. Relit la
// progression, ajoute, verse les gemmes de chaque palier de 5 franchi -- le double
// versement est impossible par construction, dernierPalierVerse est la seule source de
// verite -- puis sauvegarde. Rend tout ce que l'ecran de fin veut dire : l'avant,
// l'apres, et les gemmes versees.
async function gagnerXp(montant, piecesExplicites = null) {
  const p = await loadProgression();
  const gain = Math.max(0, Math.floor(montant || 0));
  const avant = niveauDepuisXp(p.xpTotal);
  p.xpTotal = Math.min(1000000, p.xpTotal + gain);
  const apres = niveauDepuisXp(p.xpTotal);
  let gemmesVersees = 0;
  for (let palier = p.dernierPalierVerse + 5; palier <= apres.niveauJoueur; palier += 5) {
    gemmesVersees += palier === NIVEAU_MAX ? GEMMES_PALIERS.dernierPalier : GEMMES_PALIERS.parPalier;
    p.dernierPalierVerse = palier;
  }
  // Les pieces se versent ICI et nulle part ailleurs, mais chacun apporte son
  // compte : une PARTIE arrive avec son bareme (PIECES_PARTIES, la marge de
  // victoire, calcule dans recordGameStats) ; quetes et tournoi, sans montant
  // explicite, suivent encore l'XP a deux pieces le point.
  const piecesVersees = piecesExplicites !== null
    ? Math.max(0, Math.floor(piecesExplicites))
    : gain * PIECES_SUIVANT_XP;
  if (piecesVersees > 0) await crediterPieces(piecesVersees);
  if (gemmesVersees > 0) await crediterGemmes(gemmesVersees);
  await writeProgressionRaw(JSON.stringify(p));
  return { progression: p, avant, apres, gain, gemmesVersees, piecesVersees };
}

// Un tournoi en ligne remporte. Le verrou est ICI, dans le stockage, et non dans l'appel :
// la fonction relit la sauvegarde avant de decider, si bien qu'un second appel sur le meme
// tournoi -- au redemarrage de l'application, par exemple -- ne compte rien de plus.
// La liste ne garde que les douze derniers identifiants.
async function recordTournoiGagne(tournoiId, prixGemmes = TOURNOI_ENJEU.prixVainqueur, prixXp = TOURNOI_ENJEU.xpVainqueur) {
  const stats = await loadStats();
  const vus = Array.isArray(stats.tournoisCredites) ? stats.tournoisCredites : [];
  if (vus.includes(tournoiId)) return stats;
  stats.tournoisCredites = [...vus, tournoiId].slice(-12);
  stats.tournoisGagnes = (stats.tournoisGagnes || 0) + 1;
  await writeStatsRaw(JSON.stringify(stats));
  // L'enjeu s'accroche au MEME verrou : la garde ci-dessus a deja jure que ce
  // tournoi n'avait jamais ete compte -- elle jure donc pour le prix en gemmes
  // ET pour l'XP du vainqueur (les pieces suivent l'XP toutes seules). Depuis
  // la completion par des Echos (02/09), le prix arrive de prixDuTournoi :
  // celui du document, borne par le recalcul et par les constantes -- jamais
  // au-dela, la cagnotte ne cree pas de gemmes. Ceinture locale en plus.
  const gemmesSures = Math.max(0, Math.min(TOURNOI_ENJEU.prixVainqueur, Math.floor(prixGemmes) || 0));
  const xpSur = Math.max(0, Math.min(TOURNOI_ENJEU.xpVainqueur, Math.floor(prixXp) || 0));
  await crediterGemmes(gemmesSures);
  const bilan = await gagnerXp(xpSur);
  stats.xpDePartie = { ...bilan, gemmesTournoi: gemmesSures };
  return stats;
}


// Remet les statistiques à zéro (même mécanisme de stockage hybride que ci-dessus).
async function resetStats() {
  memoryStats = null;
  await writeStatsRaw(JSON.stringify(DEFAULT_STATS));
  return { ...DEFAULT_STATS };
}

// ---------- Quetes ----------
// Chaque quete : cle unique, famille (deux quetes de la meme famille ne
// sont jamais tirees ensemble), libelle affiche, type de condition,
// objectif, XP. Le type "ordreImpose" tire un Ordre disponible au moment
// du tirage (jamais un Ordre verrouille ou "prochainement").
// Recompense : de l XP, versee par gagnerXp, et rien d autre.
const QUETES_JOUR = [
  { cle: "captures10",  famille: "captures", libelle: "Que vos rangs parlent",      type: "captures",       objectif: 10, xp: 25 },
  { cle: "captures20",  famille: "captures", libelle: "Nul ne s'échappe",     type: "captures",       objectif: 20, xp: 35 },
  { cle: "ondes3",      famille: "ondes",    libelle: "La cascade",                 type: "ondes",          objectif: 3,  xp: 30 },
  { cle: "grosseOnde",  famille: "ondes",    libelle: "Déferlante",           type: "ondeDe3",        objectif: 1,  xp: 30 },
  { cle: "parties3",    famille: "jouer",    libelle: "Le Commandant à l'oeuvre", type: "partiesJouees", objectif: 3, xp: 20 },
  { cle: "victoire1",   famille: "gagner",   libelle: "Triomphe",                   type: "victoires",      objectif: 1,  xp: 20 },
  { cle: "victoires2",  famille: "gagner",   libelle: "Double victoire",            type: "victoires",      objectif: 2,  xp: 30 },
  { cle: "ordres3",     famille: "ordres",   libelle: "L'appel des bannières", type: "ordresDistincts", objectif: 3, xp: 25 },
  { cle: "ordreImpose", famille: "ordres",   libelle: "Sous la bannière",     type: "ordreImpose",    objectif: 1,  xp: 25 },
  { cle: "histoire1",   famille: "modes",    libelle: "Chroniques",                 type: "partiesHistoire", objectif: 1, xp: 25 },
  { cle: "veteran1",    famille: "gagner",   libelle: "L'épreuve du Vétéran", type: "victoiresVeteranPlus", objectif: 1, xp: 35 },
  { cle: "confluence1", famille: "modes",    libelle: "Draft d'Ordres",             type: "partiesConfluence", objectif: 1, xp: 25 },
];
const QUETES_SEMAINE = [
  { cle: "captures100", famille: "captures", libelle: "Moisson de la semaine",      type: "captures",       objectif: 100, xp: 120 },
  { cle: "resonances3", famille: "resonances", libelle: "L'écho des rangs",   type: "resonances",     objectif: 3,   xp: 150 },
  { cle: "ondes15",     famille: "ondes",    libelle: "Le grand raz-de-marée", type: "ondes",         objectif: 15,  xp: 130 },
  { cle: "victoires10", famille: "gagner",   libelle: "Campagne victorieuse",       type: "victoires",      objectif: 10,  xp: 150 },
  { cle: "ordres8",     famille: "ordres",   libelle: "Les onze bannières",   type: "ordresDistincts", objectif: 8,  xp: 140 },
  { cle: "histoire5",   famille: "modes",    libelle: "Chronique achevée",    type: "partiesHistoire", objectif: 5,  xp: 130 },
  { cle: "seigneur3",   famille: "gagner",   libelle: "L'ascension du Seigneur",    type: "victoiresSeigneur", objectif: 3, xp: 200 },
];
const QUETES_JOUR_ACTIVES = 3;
const QUETES_SEMAINE_ACTIVES = 3;

function defQuete(cle) {
  return QUETES_JOUR.find((q) => q.cle === cle) || QUETES_SEMAINE.find((q) => q.cle === cle) || null;
}

// Le libelle affiche : "Sous la banniere" porte le nom de l Ordre tire.
function libelleDeQuete(def, quete) {
  if (def.type === "ordreImpose" && quete && quete.ordre) {
    const o = ORDERS.find((x) => x.key === quete.ordre);
    if (o) return def.libelle + " des " + o.name;
  }
  return def.libelle;
}

// La condition, derivee du type : le catalogue reste une table de donnees.
function conditionDeQuete(def, quete) {
  const n = def.objectif;
  switch (def.type) {
    case "captures": return "Capturer " + n + " cartes adverses";
    case "ondes": return n === 1 ? "Déclencher une Onde" : "Déclencher " + n + " Ondes";
    case "ondeDe3": return "Déclencher une Onde de 3 captures ou plus";
    case "partiesJouees": return "Jouer " + n + " parties";
    case "victoires": return n === 1 ? "Remporter une partie" : "Remporter " + n + " parties";
    case "ordresDistincts": return "Jouer " + n + " Ordres différents";
    case "ordreImpose": {
      const o = ORDERS.find((x) => x.key === (quete && quete.ordre));
      return "Jouer une partie avec les " + (o ? o.name : "?") + " en main";
    }
    case "partiesHistoire": return n === 1 ? "Jouer une partie d'Histoire" : "Jouer " + n + " parties d'Histoire";
    case "victoiresVeteranPlus": return "Vaincre un Écho Vétéran ou Seigneur de Guerre";
    case "victoiresSeigneur": return n === 1 ? "Vaincre le Seigneur de Guerre" : "Vaincre " + n + " fois le Seigneur de Guerre";
    case "partiesConfluence": return n === 1 ? "Jouer une partie de Confluence" : "Jouer " + n + " parties de Confluence";
    default: return "";
  }
}

// ---------- Le stockage des quetes, meme trio hybride que la bourse ----------
const DEFAUT_QUETES = {
  jour: "", quetesJour: [], rerollJour: false,
  semaine: "", quetesSemaine: [], rerollSemaine: false,
  // Le compteur de la pastille du hub : quetes accomplies pas encore vues --
  // et LEURS cles, pour que la page sache quels medaillons retourner.
  nonVus: 0,
  nonVusCles: [],
};
let memoryQuetes = null;

async function readQuetesRaw() {
  if (typeof window !== "undefined" && window.storage && window.storage.get) {
    try {
      const res = await window.storage.get("emprise-quetes");
      return res && res.value != null ? res.value : null;
    } catch (e) { return null; }
  }
  try {
    if (typeof localStorage !== "undefined") {
      const v = localStorage.getItem("emprise-quetes");
      if (v != null) return v;
    }
  } catch (e) { /* stockage bloque */ }
  return memoryQuetes;
}

async function writeQuetesRaw(str) {
  if (typeof window !== "undefined" && window.storage && window.storage.set) {
    try { await window.storage.set("emprise-quetes", str); return; } catch (e) { /* on tente la suite */ }
  }
  try {
    if (typeof localStorage !== "undefined") { localStorage.setItem("emprise-quetes", str); return; }
  } catch (e) { /* stockage bloque */ }
  memoryQuetes = str;
}

// Dates locales, sans bibliotheque : "AAAA-MM-JJ", et le lundi de la semaine.
function dateLocaleJour(d) {
  const x = d || new Date();
  const mois = String(x.getMonth() + 1).padStart(2, "0");
  const jour = String(x.getDate()).padStart(2, "0");
  return x.getFullYear() + "-" + mois + "-" + jour;
}
function lundiLocal(d) {
  const x = d ? new Date(d.getTime()) : new Date();
  // getDay : dimanche 0 ... samedi 6. Ramene au lundi de la meme semaine.
  x.setDate(x.getDate() - ((x.getDay() + 6) % 7));
  return dateLocaleJour(x);
}

// Une quete active relue depuis la sauvegarde : cle inconnue jetee, progression
// bornee, un ordreImpose sans Ordre valide est jete (le tirage completera).
function repareQueteActive(brute, catalogue) {
  if (!brute || typeof brute !== "object") return null;
  const def = catalogue.find((q) => q.cle === brute.cle);
  if (!def) return null;
  const ordre = def.type === "ordreImpose"
    && typeof brute.ordre === "string" && ORDERS.some((o) => o.key === brute.ordre)
    ? brute.ordre : null;
  if (def.type === "ordreImpose" && !ordre) return null;
  return {
    cle: def.cle,
    ordre,
    progression: Number.isFinite(brute.progression) ? Math.max(0, Math.min(def.objectif, Math.floor(brute.progression))) : 0,
    objectif: def.objectif,
    faite: brute.faite === true,
    vus: Array.isArray(brute.vus) ? brute.vus.filter((v) => typeof v === "string").slice(0, 24) : [],
  };
}

async function loadQuetes() {
  const brute = await readQuetesRaw();
  if (!brute) return JSON.parse(JSON.stringify(DEFAUT_QUETES));
  try {
    const lu = JSON.parse(brute);
    const uneListe = (liste, catalogue, plafond) => {
      const vues = new Set();
      return (Array.isArray(liste) ? liste : [])
        .map((q) => repareQueteActive(q, catalogue))
        .filter((q) => q && !vues.has(q.cle) && vues.add(q.cle))
        .slice(0, plafond);
    };
    return {
      jour: typeof lu.jour === "string" ? lu.jour : "",
      quetesJour: uneListe(lu.quetesJour, QUETES_JOUR, QUETES_JOUR_ACTIVES),
      rerollJour: lu.rerollJour === true,
      semaine: typeof lu.semaine === "string" ? lu.semaine : "",
      quetesSemaine: uneListe(lu.quetesSemaine, QUETES_SEMAINE, QUETES_SEMAINE_ACTIVES),
      rerollSemaine: lu.rerollSemaine === true,
      nonVus: Number.isFinite(lu.nonVus) ? Math.max(0, Math.min(99, Math.floor(lu.nonVus))) : 0,
      nonVusCles: Array.isArray(lu.nonVusCles)
        ? [...new Set(lu.nonVusCles.filter((k) => typeof k === "string"))].slice(-12)
        : [],
    };
  } catch (e) { return JSON.parse(JSON.stringify(DEFAUT_QUETES)); }
}

// Tire UNE quete du catalogue : jamais une cle deja active, jamais deux quetes
// de la meme famille. Pour "ordreImpose", tire aussi l Ordre -- uniquement parmi
// les disponibles, jamais le "prochainement".
function tirageQuete(catalogue, actives) {
  const familles = new Set();
  const cles = new Set();
  actives.forEach((a) => {
    cles.add(a.cle);
    const d = defQuete(a.cle);
    if (d) familles.add(d.famille);
  });
  const pool = catalogue.filter((q) => !cles.has(q.cle) && !familles.has(q.famille));
  if (!pool.length) return null;
  const def = pool[Math.floor(Math.random() * pool.length)];
  let ordre = null;
  if (def.type === "ordreImpose") {
    const dispo = ORDERS.filter(isOrderAvailable);
    if (!dispo.length) return null;
    ordre = dispo[Math.floor(Math.random() * dispo.length)].key;
  }
  return { cle: def.cle, ordre, progression: 0, objectif: def.objectif, faite: false, vus: [] };
}

// Les passages de jour et de semaine : les quetes FAITES s en vont, les autres
// restent avec leur progression, le tirage remplit les places vides, la relance
// de la periode revient. Rien d autre ne tire jamais.
function completeTirages(q) {
  let changea = false;
  const aujourdhui = dateLocaleJour();
  if (q.jour !== aujourdhui) {
    q.quetesJour = q.quetesJour.filter((a) => !a.faite);
    for (let garde = 0; q.quetesJour.length < QUETES_JOUR_ACTIVES && garde < 20; garde++) {
      const t = tirageQuete(QUETES_JOUR, q.quetesJour);
      if (!t) break;
      q.quetesJour.push(t);
    }
    q.rerollJour = false;
    q.jour = aujourdhui;
    changea = true;
  }
  const lundi = lundiLocal();
  if (q.semaine !== lundi) {
    q.quetesSemaine = q.quetesSemaine.filter((a) => !a.faite);
    for (let garde = 0; q.quetesSemaine.length < QUETES_SEMAINE_ACTIVES && garde < 20; garde++) {
      const t = tirageQuete(QUETES_SEMAINE, q.quetesSemaine);
      if (!t) break;
      q.quetesSemaine.push(t);
    }
    q.rerollSemaine = false;
    q.semaine = lundi;
    changea = true;
  }
  return changea;
}

// Chargement + tirages du moment, ecrit seulement si quelque chose a change.
async function chargerQuetesDuMoment() {
  const q = await loadQuetes();
  if (completeTirages(q)) await writeQuetesRaw(JSON.stringify(q));
  return q;
}

// La relance : une par jour pour les journalieres, une par semaine pour les
// hebdomadaires. Remplace par une quete d une AUTRE famille (la remplacee est
// dans la liste d exclusion), progression a zero, et consomme la relance.
async function relancerQuete(periode, cle) {
  const q = await loadQuetes();
  const changea = completeTirages(q);
  const auJour = periode === "jour";
  const liste = auJour ? q.quetesJour : q.quetesSemaine;
  const consommee = auJour ? q.rerollJour : q.rerollSemaine;
  const i = liste.findIndex((a) => a.cle === cle);
  if (i === -1 || liste[i].faite || consommee) {
    if (changea) await writeQuetesRaw(JSON.stringify(q));
    return q;
  }
  const exclusion = [...liste.filter((_, j) => j !== i), { cle }];
  const t = tirageQuete(auJour ? QUETES_JOUR : QUETES_SEMAINE, exclusion);
  if (t) {
    liste[i] = t;
    if (auJour) q.rerollJour = true; else q.rerollSemaine = true;
  }
  await writeQuetesRaw(JSON.stringify(q));
  return q;
}

// ---------- La progression, en fin de partie ----------
// Recoit le releve de la partie et le resultat, avance les quetes actives des
// deux periodes, verse l XP de chaque quete tout juste accomplie via gagnerXp,
// et sauvegarde UNE fois. L appelant tient la porte d entree (profil, Histoire,
// Confluence) : ici on ne fait que compter.
async function avancerQuetes(releve) {
  const q = await loadQuetes();
  completeTirages(q);
  const accomplies = [];
  for (const liste of [q.quetesJour, q.quetesSemaine]) {
    for (const a of liste) {
      if (a.faite) continue;
      const def = defQuete(a.cle);
      if (!def) continue;
      let progression = a.progression;
      switch (def.type) {
        case "captures": progression += Math.max(0, Math.floor(releve.captures || 0)); break;
        case "ondes": progression += Math.max(0, Math.floor(releve.ondes || 0)); break;
        case "ondeDe3": if ((releve.plusGrosseOnde || 0) >= 3) progression += 1; break;
        case "partiesJouees": progression += 1; break;
        case "victoires": if (releve.victoire) progression += 1; break;
        case "ordresDistincts": {
          (releve.ordresJoues || []).forEach((k) => { if (!a.vus.includes(k)) a.vus.push(k); });
          progression = a.vus.length;
          break;
        }
        case "ordreImpose": if ((releve.ordresJoues || []).includes(a.ordre)) progression = def.objectif; break;
        case "partiesHistoire": if (releve.partieHistoire) progression += 1; break;
        case "victoiresVeteranPlus":
          if (releve.victoire && (releve.difficulteEcho === "avance" || releve.difficulteEcho === "expert")) progression += 1;
          break;
        case "victoiresSeigneur": if (releve.victoire && releve.difficulteEcho === "expert") progression += 1; break;
        case "partiesConfluence": if (releve.partieConfluence) progression += 1; break;
        case "resonances": progression += Math.max(0, Math.floor(releve.resonances || 0)); break;
        default: break;
      }
      a.progression = Math.max(0, Math.min(def.objectif, progression));
      if (a.progression >= def.objectif) {
        a.faite = true;
        await gagnerXp(def.xp);
        accomplies.push({ cle: def.cle, libelle: libelleDeQuete(def, a), xp: def.xp });
      }
    }
  }
  if (accomplies.length) {
    q.nonVus = Math.min(99, (q.nonVus || 0) + accomplies.length);
    q.nonVusCles = [...new Set([...(q.nonVusCles || []), ...accomplies.map((a) => a.cle)])].slice(-12);
  }
  await writeQuetesRaw(JSON.stringify(q));
  return { quetes: q, accomplies };
}

// ---------- Niveaux de Commandant ----------
// Progression d'ESSAI avant la sortie : comme le solde d'essai de la bourse,
// elle sera remise a zero au lancement.
const NIVEAU_MAX = 50;
// XP demandee pour passer CHAQUE niveau de la tranche (du niveau 2 au 10 : 100
// par niveau, etc.). Total pour le niveau 50 : environ 20 000 XP.
const NIVEAUX_XP = [
  { jusqua: 10, cout: 100 },
  { jusqua: 25, cout: 250 },
  { jusqua: 40, cout: 500 },
  { jusqua: 50, cout: 800 },
];
// XP par partie comptee. La cle "classe" est une base, completee par la ligue.
// NB verifie dans le code : l'egalite n'arrive JAMAIS ici -- une egalite persistante
// donne la victoire au second joueur (voir le calcul de winner). Son bareme est fixe
// d'avance pour le jour ou une vraie egalite existerait.
const XP_PARTIES = {
  // Contre un Echo, l'XP suit sa difficulte : un bot faible rapporte peu,
  // farmer le Novice ne vaut pas le coup. Les cles sont celles de
  // DIFFICULTIES. Une partie d'Histoire est aussi un combat de bot : meme
  // table, plus une prime fixe. Difficulte absente (partie amicale en ligne) :
  // intermediaire, on ne plante jamais.
  victoireEcho: { debutant: 8, intermediaire: 12, avance: 16, expert: 20 },
  bonusHistoire: 10,
  victoireClasseBase: 30,
  victoireClasseParLigue: 10, // x index de ligue : Bronze 0 -> Legende 4
  defaite: 5,
  defaiteClassee: 8,
  egalite: 10,
  // tournoiRemporte a vecu ici (150) ; l'XP du tournoi en ligne vit desormais
  // dans TOURNOI_ENJEU.xpVainqueur, versee au meme verrou que le prix en gemmes.
};
// Gemmes versees a chaque palier de 5 niveaux.
const GEMMES_PALIERS = { parPalier: 50, dernierPalier: 150 }; // niveau 50 : 150

// Le cout du passage VERS ce niveau : la premiere tranche qui l'atteint.
function coutDuNiveauXp(n) {
  const tranche = NIVEAUX_XP.find((t) => n <= t.jusqua);
  return tranche ? tranche.cout : null;
}

// Pure, sans etat : le niveau n'est JAMAIS stocke, il se recalcule du total. Relever le
// plafond plus tard fera rattraper tout le monde sans migration.
function niveauDepuisXp(xpTotal) {
  let reste = Math.max(0, Math.floor(xpTotal || 0));
  let niveauJoueur = 1;
  for (let n = 2; n <= NIVEAU_MAX; n++) {
    const cout = coutDuNiveauXp(n);
    if (reste < cout) break;
    reste -= cout;
    niveauJoueur = n;
  }
  const xpPourSuivant = niveauJoueur >= NIVEAU_MAX ? null : coutDuNiveauXp(niveauJoueur + 1);
  return { niveauJoueur, xpDansNiveau: reste, xpPourSuivant };
}

// ---------- 2. Le stockage, meme mecanisme hybride que la bourse ----------
const DEFAUT_PROGRESSION = { xpTotal: 0, dernierPalierVerse: 0 };
let memoryProgression = null;

async function readProgressionRaw() {
  if (typeof window !== "undefined" && window.storage && window.storage.get) {
    try {
      const res = await window.storage.get("emprise-progression");
      return res && res.value != null ? res.value : null;
    } catch (e) { return null; }
  }
  try {
    if (typeof localStorage !== "undefined") {
      const v = localStorage.getItem("emprise-progression");
      if (v != null) return v;
    }
  } catch (e) { /* stockage bloque */ }
  return memoryProgression;
}

async function writeProgressionRaw(str) {
  if (typeof window !== "undefined" && window.storage && window.storage.set) {
    try { await window.storage.set("emprise-progression", str); return; } catch (e) { /* on tente la suite */ }
  }
  try {
    if (typeof localStorage !== "undefined") { localStorage.setItem("emprise-progression", str); return; }
  } catch (e) { /* stockage bloque */ }
  memoryProgression = str;
}

// La lecture repare : totaux bornes, sauvegarde abimee ramenee aux valeurs par defaut.
async function loadProgression() {
  const brut = await readProgressionRaw();
  if (!brut) return { ...DEFAUT_PROGRESSION };
  try {
    const lu = JSON.parse(brut);
    return {
      xpTotal: Number.isFinite(lu.xpTotal) ? Math.max(0, Math.min(1000000, Math.floor(lu.xpTotal))) : 0,
      dernierPalierVerse: Number.isFinite(lu.dernierPalierVerse) ? Math.max(0, Math.min(NIVEAU_MAX, Math.floor(lu.dernierPalierVerse))) : 0,
    };
  } catch (e) { return { ...DEFAUT_PROGRESSION }; }
}

// ---------- La bourse : gemmes et possessions (meme stockage hybride) ----------
// Le solde d'essai. VERSE UNE FOIS, marque dans la sauvegarde, et affiche comme un essai
// a l'ecran : le jour du lancement cette constante tombe a zero, personne ne garde de
// gemmes gratuites, et le champ essaiVerse dit qui en avait recu.
// L'ancre du plan : 100 gemmes pour environ 1 euro. La mention dit ce que chaque palier
// rend de plus par euro ; la plus grande porte « Meilleure offre ». Les paliers de
// reserve (5900, 14000) existent dans le plan mais pas ici : pas au lancement.
// prixDit : « euro » en toutes lettres, pour le lecteur d'ecran qui lit mal le symbole.
// doublePremierAchat : le drapeau d'AFFICHAGE du bonus x2 -- vrai par defaut
// tant que rien ne s'achete. La mecanique reelle (consommer le drapeau apres le
// premier achat) se branchera avec les paiements, pas avant.
const PACKS_GEMMES = [
  { cle: "poignee", nom: "Poignée de gemmes", gemmes: 80, prix: "0,99 €", prixDit: "0,99 euro", mention: "", image: "/boutique/pack-poignee.webp", doublePremierAchat: true },
  { cle: "bourse", nom: "Bourse de gemmes", gemmes: 500, prix: "4,99 €", prixDit: "4,99 euros", mention: "+24 %", image: "/boutique/pack-bourse.webp", doublePremierAchat: true },
  { cle: "coffret", nom: "Coffret de gemmes", gemmes: 1200, prix: "9,99 €", prixDit: "9,99 euros", mention: "+48 %", image: "/boutique/pack-coffret.webp", doublePremierAchat: true },
  { cle: "coffre", nom: "Coffre de gemmes", gemmes: 2600, prix: "19,99 €", prixDit: "19,99 euros", mention: "Meilleure offre", image: "/boutique/pack-coffre.webp", doublePremierAchat: true },
];

// ---------- Pieces ----------
// Les pieces DE PARTIE ne suivent plus l'XP : elles recompensent la maniere de
// jouer, par la MARGE DE VICTOIRE. Bareme calibre sur 2500 parties du moteur
// reel (outils-equilibrage/bareme.cjs) : l'ecart de score va de 1 a 15, jamais
// pair (le point du premier joueur interdit l'egalite), 3,92 de moyenne, 33 %
// des parties a 1 point. Les captures ne discriminent pas (10,4 contre 8,4),
// elles ne paient donc rien.
const PIECES_PARTIES = {
  // La marge de victoire : chaque point d'ecart au score final paie, jusqu'a
  // un plafond -- au-dela, l'ecart en dit plus sur la faiblesse d'en face
  // que sur le talent du vainqueur. Valeurs calibrees sur 2500 parties.
  margePlafond: 10,
  classe: {
    baseVictoire: 40,
    parLigue: 20,          // x index de ligue : Bronze 0 -> Legende 4
    parEcart: 5,
    baseDefaite: 12,
    primeDefaiteSerree: 8, // quand l'ecart vaut 1
  },
  echo: {
    baseVictoire: { debutant: 8, intermediaire: 16, avance: 24, expert: 32 },
    parEcart: 2,
    baseDefaite: 8,
    primeDefaiteSerree: 6,
  },
  bonusHistoire: 20,
};
// Quetes et tournoi en ligne, eux, suivent encore l'XP : deux pieces par point.
// C'est l'ancien lien pieces-XP, conserve pour ces deux sources seulement (la
// spec des pieces gele leur economie) -- les parties passent par le bareme.
const PIECES_SUIVANT_XP = 2;
// Anti-farm des victoires express (01/09) : une fin FORCEE en ligne (abandon
// ou forfait, vainqueurForce pose) avec MOINS de ce nombre de cartes posees
// sur le plateau partage est une partie ECOURTEE. Le vainqueur y touche la
// moitie de la base d'XP (sans part de ligue) et le bareme des pieces nourri
// d'un ecart nul (base seule) : deux comptes complices ne peuvent plus
// enchainer abandon express et victoire express. Les trophees, eux, ne
// bougent JAMAIS ici : quitter reste une defaite pleine au classement, sinon
// quitter deviendrait une arme contre la victime.
const PARTIE_ECOURTEE_COUPS = 4;

// ---------- Rencontres classees du jour ----------
// Anti-complices (01/09) : deux joueurs ne doivent pas pouvoir se nourrir en
// trophees. Au-dela de ce nombre de parties classees TERMINEES le meme jour
// contre le MEME adversaire, la rencontre suivante se joue et se paie en
// AMICALE -- zero trophee des deux cotes, tarifs non classes, Flamme non
// nourrie. On ne bloque JAMAIS la rencontre elle-meme : la salle d attente
// n a qu une place, un refus affamerait toute la file.
const RENCONTRES_CLASSEES_JOUR = 3;
const DEFAUT_RENCONTRES = { jour: "", parAdversaire: {} };
let memoryRencontres = null;

async function readRencontresRaw() {
  if (typeof window !== "undefined" && window.storage && window.storage.get) {
    try {
      const res = await window.storage.get("emprise-rencontres");
      return res && res.value != null ? res.value : null;
    } catch (e) { /* pont en panne : on tente les couches locales */ }
  }
  try {
    if (typeof localStorage !== "undefined") {
      const v = localStorage.getItem("emprise-rencontres");
      if (v != null) return v;
    }
  } catch (e) { /* stockage bloque */ }
  return memoryRencontres;
}

async function writeRencontresRaw(str) {
  if (typeof window !== "undefined" && window.storage && window.storage.set) {
    try { await window.storage.set("emprise-rencontres", str); return; } catch (e) { /* on tente la suite */ }
  }
  try {
    if (typeof localStorage !== "undefined") { localStorage.setItem("emprise-rencontres", str); return; }
  } catch (e) { /* stockage bloque */ }
  memoryRencontres = str;
}

// Relecture assainie : un jour different d aujourd hui (le jour LOCAL, celui
// de la Flamme) remet tout a zero ; une cle vide ou demesuree est jetee ; un
// compte est un entier borne 0..1000.
async function loadRencontres() {
  const propre = { ...DEFAUT_RENCONTRES, jour: dateLocaleJour(), parAdversaire: {} };
  try {
    const raw = await readRencontresRaw();
    if (!raw) return propre;
    const lu = JSON.parse(raw);
    if (!lu || lu.jour !== propre.jour) return propre;
    if (lu.parAdversaire && typeof lu.parAdversaire === "object") {
      for (const [uid, n] of Object.entries(lu.parAdversaire)) {
        // 132 et non 128 : la famille classique prefixe sa cle de deux
        // caracteres, un uid a la borne d avant se serait fait jeter.
        if (!uid || typeof uid !== "string" || uid.length > 132) continue;
        if (!Number.isFinite(n)) continue;
        propre.parAdversaire[uid] = Math.max(0, Math.min(1000, Math.floor(n)));
      }
    }
    return propre;
  } catch (e) {
    return propre;
  }
}

// Les deux familles appariees comptent SEPAREMENT (01/09) : trois classees et
// trois classiques par jour contre le meme adversaire, chacune son quota. Une
// seule table, deux espaces de cles -- la classique prefixe le sien, si bien
// qu aucune partie ne peut consommer le quota de l autre famille.
function cleRencontre(uid, famille) { return famille === "classique" ? "c:" + uid : uid; }

// Combien de parties appariees deja TERMINEES aujourd hui contre cet
// adversaire precis, dans CETTE famille.
async function rencontresContre(uid, famille = "classe") {
  if (!uid) return 0;
  const r = await loadRencontres();
  return r.parAdversaire[cleRencontre(uid, famille)] || 0;
}

// Une partie appariee TERMINEE de plus contre cet adversaire -- declassee
// comprise : la 5e et la 6e restent amicales jusqu a demain.
async function compterRencontre(uid, famille = "classe") {
  if (!uid) return;
  const r = await loadRencontres();
  const cle = cleRencontre(uid, famille);
  r.parAdversaire[cle] = Math.min(1000, (r.parAdversaire[cle] || 0) + 1);
  await writeRencontresRaw(JSON.stringify(r));
}
// Conversion, a sens unique strict : les gemmes deviennent des pieces,
// jamais l'inverse. Taux plat, affiche en toutes lettres au joueur.
const PIECES_PAR_GEMME = 10;
// Montants predefinis de l'ecran de conversion (en gemmes), chacun avec son
// visuel -- la pile, la bourse, le coffret. Le chemin des images vit ICI,
// jamais en dur dans le JSX.
const CONVERSIONS = [
  { gemmes: 100, image: "/boutique/pieces-pile.png" },
  { gemmes: 250, image: "/boutique/pieces-bourse.png" },
  { gemmes: 500, image: "/boutique/pieces-coffret.png" },
];

// ---------- Flamme quotidienne ----------
// Serie classique : +1 par jour ou une partie CLASSEE se livre (victoire ou
// defaite), retombe a zero apres un jour manque -- choix assume du createur.
// Les paliers se reversent a chaque nouvelle serie qui les atteint. Deux
// adoucissements font partie du dessin, ne pas les "simplifier" : le record ne
// retombe jamais, et les pieces deja versees ne se reprennent jamais.
// AUCUNE protection de Flamme payante -- ni gemmes, ni pieces, ni publicite,
// ni rachat d'aucune sorte : ne jamais en ajouter une.
// Les sept parts de la Flamme : un duel classe par jour, sept jours d affilee.
// FlammeVivante remplit un septieme par jour ; ce nombre-ci sert au succes.
const FLAMME_PARTS = 7;
const FLAMME_PALIERS = [
  { jours: 7,   pieces: 200 },
  { jours: 30,  pieces: 1000 },
  { jours: 100, pieces: 5000 },
];
const DEFAUT_FLAMME = { serie: 0, record: 0, dernierJour: "", palierVerseSerie: 0 };
let memoryFlamme = null;

async function readFlammeRaw() {
  if (typeof window !== "undefined" && window.storage && window.storage.get) {
    try {
      const res = await window.storage.get("emprise-flamme");
      return res && res.value != null ? res.value : null;
    } catch (e) { /* pont en panne : on TENTE les couches locales au lieu de
      conclure a l'absence -- un rate transitoire qui ferait passer la
      sauvegarde pour vide conduirait nourrirFlamme a ecrire une serie neuve
      par-dessus le record a vie. */ }
  }
  try {
    if (typeof localStorage !== "undefined") {
      const v = localStorage.getItem("emprise-flamme");
      if (v != null) return v;
    }
  } catch (e) { /* stockage bloque */ }
  return memoryFlamme;
}

async function writeFlammeRaw(str) {
  if (typeof window !== "undefined" && window.storage && window.storage.set) {
    try { await window.storage.set("emprise-flamme", str); return; } catch (e) { /* on tente la suite */ }
  }
  try {
    if (typeof localStorage !== "undefined") { localStorage.setItem("emprise-flamme", str); return; }
  } catch (e) { /* stockage bloque */ }
  memoryFlamme = str;
}

// La veille d'un jour "AAAA-MM-JJ", par le calendrier : new Date(a, m, j - 1)
// gere les fins de mois et l'heure d'ete, la ou une soustraction de
// millisecondes peut sauter un jour.
function veilleDeJour(jour) {
  const [a, m, j] = jour.split("-").map(Number);
  return dateLocaleJour(new Date(a, m - 1, j - 1));
}

// L'extinction : un dernier jour qui n'est ni aujourd'hui ni hier eteint la
// serie et remet le compteur de palier a zero, pour que la serie suivante
// reverse les paliers qu'elle atteindra. Le record, lui, ne bouge JAMAIS.
// Le jour de reference vient de l'appelant, echantillonne UNE seule fois :
// minuit ne peut pas tomber entre deux lectures d'horloge.
// Rend vrai si quelque chose a change (a l'appelant de sauvegarder).
function eteindreFlammeSiFroide(f, aujourdhui) {
  if (f.dernierJour === aujourdhui || f.dernierJour === veilleDeJour(aujourdhui)) return false;
  if (f.serie === 0 && f.palierVerseSerie === 0) return false;
  f.serie = 0;
  f.palierVerseSerie = 0;
  return true;
}

// Lecture reparatrice, comme la bourse : nombres bornes (0 a 100 000), date au
// format AAAA-MM-JJ ou vide. L'extinction s'evalue a CHAQUE lecture -- au
// chargement de l'application comme juste avant d'incrementer -- et se
// sauvegarde aussitot : l'affichage et l'increment lisent le meme etat.
async function loadFlamme(jourDeReference) {
  const aujourdhui = jourDeReference || dateLocaleJour();
  const brut = await readFlammeRaw();
  const f = { ...DEFAUT_FLAMME };
  if (brut) {
    try {
      const lu = JSON.parse(brut);
      const borne = (n) => (Number.isFinite(n) ? Math.max(0, Math.min(100000, Math.floor(n))) : 0);
      f.serie = borne(lu.serie);
      f.record = borne(lu.record);
      f.palierVerseSerie = borne(lu.palierVerseSerie);
      f.dernierJour = typeof lu.dernierJour === "string" && /^\d{4}-\d{2}-\d{2}$/.test(lu.dernierJour) ? lu.dernierJour : "";
    } catch (e) { /* sauvegarde abimee : on repart d'une flamme eteinte */ }
  }
  // Une date d'un jour A VENIR (horloge rendue, fuseau traverse vers l'ouest)
  // bloquerait la premiere partie de ce jour-la : elle se vide, et l'extinction
  // juste dessous tranche le sort de la serie.
  if (f.dernierJour > aujourdhui) f.dernierJour = "";
  // Le record ne peut pas etre sous la serie en cours : repare AVANT l'extinction,
  // pour que la serie sauve son record meme si elle s'eteint a l'instant.
  if (f.record < f.serie) f.record = f.serie;
  if (eteindreFlammeSiFroide(f, aujourdhui)) await writeFlammeRaw(JSON.stringify(f));
  return f;
}

// La PREMIERE partie classee du jour nourrit la Flamme : +1, le record suit, et
// chaque palier que cette serie atteint sans l'avoir touche se verse. Une seule
// incrementation par jour calendaire, quoi qu'il arrive. Le marqueur
// (palierVerseSerie) s'ecrit AVANT le credit des pieces : entre les deux, une
// panne coute un versement plutot que d'en doubler un.
async function nourrirFlamme() {
  // Le jour s'echantillonne UNE fois et voyage jusqu'a l'extinction : minuit
  // entre deux lectures d'horloge ne peut plus fausser la decision.
  const aujourdhui = dateLocaleJour();
  const f = await loadFlamme(aujourdhui); // l'extinction vient d'etre evaluee ici
  if (f.dernierJour === aujourdhui) return { flamme: f, jourNouveau: false, piecesVersees: 0 };
  f.serie += 1;
  f.dernierJour = aujourdhui;
  if (f.record < f.serie) f.record = f.serie;
  let pieces = 0;
  for (const palier of FLAMME_PALIERS) {
    if (f.serie >= palier.jours && f.palierVerseSerie < palier.jours) {
      pieces += palier.pieces;
      f.palierVerseSerie = palier.jours;
    }
  }
  await writeFlammeRaw(JSON.stringify(f));
  if (pieces > 0) await crediterPieces(pieces);
  return { flamme: f, jourNouveau: true, piecesVersees: pieces };
}

// ---------- Tournoi en ligne a enjeu ----------
// 8 joueurs misent 20 gemmes : cagnotte 160. SEUL le vainqueur recoit des
// gemmes (100) -- decision du Commandant, le prix du finaliste (40) a vecu.
// Le reste sort du jeu : la cagnotte ne cree jamais de gemmes.
// Le tournoi SOLO, lui, reste gratuit et sans prix : payer pour des bots
// serait une pompe a gemmes ou une arnaque.
const TOURNOI_ENJEU = {
  entree: 20,          // gemmes debitees a l'inscription
  prixVainqueur: 100,  // gemmes
  xpVainqueur: 300,    // XP en plus (les pieces suivent toutes seules)
};
// ---------- La completion d un tournoi en ligne par des Echos (02/09) ----------
// L anti pompe a gemmes, en une ligne : N humains misent N x 20 gemmes, et le
// prix du vainqueur vaut Math.round(N x 12,5) -- toujours STRICTEMENT sous la
// cagnotte. 8 humains : 100, comme avant. 3 : 38. 2 : 25. Completer avec des
// Echos ne cree donc JAMAIS de gemmes ; et si un Echo gagne, personne ne
// recoit rien, la cagnotte brule entierement : c est le prix du risque, et
// c est ce qui rend la completion honnete. L XP du vainqueur suit la meme
// proportion. La regle d or heritee du tournoi solo tient : la cagnotte ne
// cree jamais de gemmes.
const TOURNOI_COMPLETE_ECHOS_S = 120; // delai avant de proposer les Echos
const TOURNOI_PRIX_PAR_HUMAIN = 12.5; // gemmes par humain inscrit
const TOURNOI_ECHO_DIFF = "avance";   // le niveau des Echos qui completent : Veteran
// Le forfait d un match contre un Echo (03/09). Contre un HUMAIN, l adversaire
// constate le silence dans le document de partie et ecrit le forfait ; face a
// un Echo il n y a ni document ni adversaire, et un match jamais joue gelait
// l arbre pour les huit. Un simple delai ne suffit pas : le match local n a
// pas de minuteur, un joueur qui reflechit serait declare forfait. D ou un
// SIGNE DE VIE, ecrit par le joueur pendant qu il joue ; le forfait ne tombe
// qu apres un silence complet, donc sur une application fermee.
const TOURNOI_ECHO_FORFAIT_MS = 300000;  // 5 min sans le moindre signe de vie
const TOURNOI_ECHO_BATTEMENT_MS = 60000; // le signe de vie, pendant le match
// Un siege d Echo dans joueurs : jamais un uid, jamais un pseudo qui imite un
// humain -- un prefixe que rien d autre ne porte.
function estEchoTournoi(uid) { return typeof uid === "string" && uid.startsWith("echo:"); }
// Le prix REEL d un tournoi : celui du document (ecrit a la completion),
// borne par le recalcul depuis ses joueurs ET par les constantes -- un
// document trafique ne peut pas gonfler la cagnotte, elle ne cree jamais de
// gemmes. Vieux tournois sans champ : les constantes pleines, comme avant.
function prixDuTournoi(t) {
  const joueurs = (t && Array.isArray(t.joueurs)) ? t.joueurs : [];
  const humains = joueurs.length ? joueurs.filter((u) => !estEchoTournoi(u)).length : 8;
  const plafondGemmes = Math.min(TOURNOI_ENJEU.prixVainqueur, Math.round(humains * TOURNOI_PRIX_PAR_HUMAIN));
  const plafondXp = Math.min(TOURNOI_ENJEU.xpVainqueur, Math.round((TOURNOI_ENJEU.xpVainqueur * humains) / 8));
  const gemmes = typeof t?.prixGemmes === "number" ? Math.max(0, Math.min(plafondGemmes, Math.floor(t.prixGemmes))) : plafondGemmes;
  const xp = typeof t?.prixXp === "number" ? Math.max(0, Math.min(plafondXp, Math.floor(t.prixXp))) : plafondXp;
  return { gemmes, xp, humains };
}
// Graine numerique d une chaine, pour l alea deterministe des matchs d Echos.
function graineDeChaine(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h | 0;
}

